t["Too much pressure! Disengage!"] = "\\u0627\\u0644\\u0636\\u063A\\u0637 \\u0643\\u062A\\u064A\\u0631! \\u0641\\u0643 \\u0627\\u0644\\u0627\\u0634\\u062A\\u0628\\u0627\\u0643!"
t["Too shaken to aim properly. I'm stepping back to breathe."] = "\\u0645\\u0647\\u0632\\u0648\\u0632\\u0629 \\u0643\\u062A\\u064A\\u0631 \\u0644\\u0635\\u064A\\u0628 \\u0645\\u0646\\u064A\\u062D. \\u0639\\u0645 \\u0627\\u0631\\u062C\\u0639 \\u0627\\u062A\\u0646\\u0641\\u0633."
t["Too tired to watch your back. I'm recovering beside you."] = "\\u062A\\u0639\\u0628\\u0627\\u0646\\u0629 \\u0643\\u062A\\u064A\\u0631 \\u0644\\u0627\\u062D\\u0645\\u064A \\u0636\\u0647\\u0631\\u0643. \\u0631\\u062D \\u0627\\u0631\\u062A\\u0627\\u062D \\u062C\\u0646\\u0628\\u0643."
t["Too worn to last the fight. I'm checking our spares."] = "\\u0645\\u0647\\u062A\\u0631\\u064A \\u0643\\u062A\\u064A\\u0631 \\u0644\\u064A\\u0643\\u0645\\u0644 \\u0627\\u0644\\u0642\\u062A\\u0627\\u0644. \\u0639\\u0645 \\u0634\\u064A\\u0651\\u0643 \\u0639\\u0627\\u0644\\u0627\\u062D\\u062A\\u064A\\u0627\\u0637."
t["Tool requirement unresolved. The plot has to wait."] = "\\u0644\\u0633\\u0627 \\u0627\\u0644\\u0639\\u062F\\u0629 \\u0646\\u0627\\u0642\\u0635\\u0629. \\u0627\\u0644\\u0623\\u0631\\u0636 \\u0644\\u0627\\u0632\\u0645 \\u062A\\u0633\\u062A\\u0646\\u0649."
t["Torque wrench, good sockets, and nobody took the creeper. Heaven."] = "\\u0645\\u0641\\u062A\\u0627\\u062D \\u0639\\u0632\\u0645\\u060C \\u0633\\u0648\\u0643\\u064A\\u062A\\u0627\\u062A \\u0645\\u0646\\u064A\\u062D\\u0629\\u060C \\u0648\\u0645\\u0627 \\u062D\\u062F\\u0627 \\u0623\\u062E\\u062F \\u0644\\u0648\\u062D \\u0627\\u0644\\u0632\\u062D\\u0641. \\u062C\\u0646\\u0629."
t["Tough crowd."] = "\\u062C\\u0645\\u0647\\u0648\\u0631 \\u0635\\u0639\\u0628."
t["Tour notice says every barrel is part of our future. Optimistic, that."] = "\\u0625\\u0639\\u0644\\u0627\\u0646 \\u0627\\u0644\\u062C\\u0648\\u0644\\u0629 \\u0628\\u064A\\u0642\\u0648\\u0644 \\u0643\\u0644 \\u0628\\u0631\\u0645\\u064A\\u0644 \\u062C\\u0632\\u0621 \\u0645\\u0646 \\u0645\\u0633\\u062A\\u0642\\u0628\\u0644\\u0646\\u0627. \\u0645\\u062A\\u0641\\u0627\\u0626\\u0644\\u064A\\u0646."
t["Travel time increasing. Distance unchanged. Interesting fuel economy."] = "\\u0648\\u0642\\u062A \\u0627\\u0644\\u0631\\u062D\\u0644\\u0629 \\u0639\\u0645 \\u064A\\u0632\\u064A\\u062F \\u0648\\u0627\\u0644\\u0645\\u0633\\u0627\\u0641\\u0629 \\u0646\\u0641\\u0633\\u0647\\u0627. \\u0627\\u0633\\u062A\\u0647\\u0644\\u0627\\u0643 \\u0628\\u0646\\u0632\\u064A\\u0646 \\u0645\\u062B\\u064A\\u0631."
t["Treadmills. Running in place. We've all been doing that since July."] = "\\u062C\\u0647\\u0627\\u0632 \\u0627\\u0644\\u0631\\u0643\\u0636. \\u0631\\u0643\\u0636 \\u0628\\u0627\\u0644\\u0645\\u062D\\u0644. \\u0643\\u0644\\u0646\\u0627 \\u0639\\u0645 \\u0646\\u0639\\u0645\\u0644 \\u0647\\u064A\\u0643 \\u0645\\u0646 \\u062A\\u0645\\u0648\\u0632."
t["Treat first, then check the adjacent plots."] = "\\u0627\\u0644\\u0639\\u0644\\u0627\\u062C \\u0623\\u0648\\u0644\\u060C \\u0648\\u0628\\u0639\\u062F\\u064A\\u0646 \\u0645\\u0646\\u0634\\u0648\\u0641 \\u0627\\u0644\\u0623\\u0631\\u0627\\u0636\\u064A \\u0627\\u0644\\u0644\\u064A \\u062C\\u0646\\u0628\\u0647\\u0627."
t["Treating the plants. Nobody panic, especially the cabbage."] = "\\u0639\\u0645 \\u0639\\u0627\\u0644\\u062C \\u0627\\u0644\\u0632\\u0631\\u0639. \\u0645\\u0627 \\u062D\\u062F\\u0627 \\u064A\\u062E\\u0627\\u0641\\u060C \\u0648\\u062E\\u0635\\u0648\\u0635\\u064A \\u0627\\u0644\\u0645\\u0644\\u0641\\u0648\\u0641."
t["Trust comes slowly for me now."] = "\\u0627\\u0644\\u062B\\u0642\\u0629 \\u0635\\u0627\\u0631\\u062A \\u062A\\u062C\\u064A \\u0639\\u0646\\u062F\\u064A \\u0639\\u0627\\u0644\\u0628\\u0637\\u064A\\u0621."
t["Truth is:"] = "\\u0627\\u0644\\u062D\\u0642\\u064A\\u0642\\u0629:"
t["Turn it up a touch. That sounds useful."] = "\\u0639\\u0644\\u0651\\u064A \\u0627\\u0644\\u0635\\u0648\\u062A \\u0634\\u0648\\u064A. \\u0647\\u0627\\u062F \\u0634\\u0643\\u0644\\u0647 \\u0645\\u0641\\u064A\\u062F."
t["Turning the dial. Keep an ear on the door."] = "\\u0639\\u0645 \\u062F\\u0648\\u0651\\u0631 \\u0627\\u0644\\u0645\\u0624\\u0634\\u0631. \\u062E\\u0644\\u064A \\u0623\\u062F\\u0646\\u0643 \\u0639\\u0627\\u0644\\u0628\\u0627\\u0628."
t["Twelve herbs and spices my foot. It was salt and prayer."] = "\\u0627\\u062A\\u0646\\u0627\\u0639\\u0634 \\u0628\\u0647\\u0627\\u0631 \\u0648\\u0639\\u0634\\u0628\\u0629 \\u0642\\u0627\\u0644. \\u0643\\u0627\\u0646 \\u0645\\u0644\\u062D \\u0648\\u0635\\u0644\\u0627\\u0629."
t["Twenty-four hours, seven days. They meant it."] = "\\u0623\\u0631\\u0628\\u0639\\u0629 \\u0648\\u0639\\u0634\\u0631\\u064A\\u0646 \\u0633\\u0627\\u0639\\u0629\\u060C \\u0633\\u0628\\u0639 \\u0623\\u064A\\u0627\\u0645. \\u0648\\u0643\\u0627\\u0646\\u0648\\u0627 \\u064A\\u0642\\u0635\\u062F\\u0648\\u0647\\u0627."
t["Twice is enough. Back away from me."] = "\\u0645\\u0631\\u062A\\u064A\\u0646 \\u0628\\u0643\\u0641\\u064A. \\u0627\\u0628\\u0639\\u062F \\u0639\\u0646\\u064A."
t["Two angles of attack. Withdraw."] = "\\u0647\\u062C\\u0648\\u0645 \\u0645\\u0646 \\u062C\\u0647\\u062A\\u064A\\u0646. \\u0627\\u0646\\u0633\\u062D\\u0628."
t["Two beds, one lock. Used to be a holiday."] = "\\u062A\\u062E\\u062A\\u064A\\u0646 \\u0648\\u0642\\u0641\\u0644 \\u0648\\u0627\\u062D\\u062F. \\u0643\\u0627\\u0646\\u062A \\u0647\\u064A \\u0639\\u0637\\u0644\\u0629."
t["Two confirmed, moving together."] = "\\u062A\\u0646\\u064A\\u0646 \\u0623\\u0643\\u064A\\u062F, \\u0645\\u0627\\u0634\\u064A\\u064A\\u0646 \\u0633\\u0648\\u0627."
t["Two contacts. Reset the fight!"] = "\\u062A\\u0646\\u064A\\u0646. \\u0631\\u062A\\u0628 \\u0627\\u0644\\u0645\\u0639\\u0631\\u0643\\u0629 \\u0645\\u0646 \\u062C\\u062F\\u064A\\u062F!"
t["Two deadheads crossing ahead."] = "\\u062A\\u0646\\u064A\\u0646 \\u0645\\u064A\\u062A\\u064A\\u0646 \\u0642\\u0627\\u0637\\u0639\\u064A\\u0646 \\u0642\\u062F\\u0627\\u0645\\u0646\\u0627."
t["Two nails short. The apocalypse remains poorly supplied."] = "\\u0646\\u0627\\u0642\\u0635\\u0646\\u0627 \\u0628\\u0633\\u0645\\u0627\\u0631\\u064A\\u0646. \\u0646\\u0647\\u0627\\u064A\\u0629 \\u0627\\u0644\\u0639\\u0627\\u0644\\u0645 \\u0644\\u0633\\u0627 \\u062A\\u0645\\u0648\\u064A\\u0646\\u0647\\u0627 \\u062A\\u0639\\u0628\\u0627\\u0646."
t["Two nails. Civilization ended over less."] = "\\u0628\\u0633\\u0645\\u0627\\u0631\\u064A\\u0646. \\u062D\\u0636\\u0627\\u0631\\u0627\\u062A \\u0627\\u0646\\u062A\\u0647\\u062A \\u0639\\u0644\\u0649 \\u0623\\u0642\\u0644 \\u0645\\u0646 \\u0647\\u064A\\u0643."
t["Two now. Of course there are two."] = "\\u0647\\u0644\\u0623 \\u0635\\u0627\\u0631\\u0648\\u0627 \\u062A\\u0646\\u064A\\u0646. \\u0637\\u0628\\u0639\\u0627 \\u062A\\u0646\\u064A\\u0646."
t["Two of them. Fine!"] = "\\u062A\\u0646\\u064A\\u0646 \\u0645\\u0646\\u0646. \\u0645\\u0627\\u0634\\u064A!"
t["Two of them. Stay close and don't get between them."] = "\\u062A\\u0646\\u064A\\u0646 \\u0645\\u0646\\u0646. \\u062E\\u0644\\u064A\\u0643 \\u0642\\u0631\\u064A\\u0628 \\u0648\\u0644\\u0627 \\u062A\\u0648\\u0642\\u0641 \\u0628\\u064A\\u0646\\u0627\\u062A\\u0646."
t["Two of them. We can split them."] = "\\u062A\\u0646\\u064A\\u0646 \\u0645\\u0646\\u0646. \\u0641\\u064A\\u0646\\u0627 \\u0646\\u0641\\u0631\\u0642\\u0646."
t["Two of y'all? Line up nice!"] = "\\u062A\\u0646\\u064A\\u0646\\u0643\\u0646? \\u0635\\u0641\\u0648\\u0627 \\u0628\\u0627\\u0644\\u062F\\u0648\\u0631!"
t["Two targets. Don't let them line up on us!"] = "\\u0647\\u062F\\u0641\\u064A\\u0646. \\u0644\\u0627 \\u062A\\u062E\\u0644\\u064A\\u0647\\u0646 \\u064A\\u0635\\u0637\\u0641\\u0648\\u0627 \\u0639\\u0644\\u064A\\u0646\\u0627!"
t["Two targets. Focus one down."] = "\\u0647\\u062F\\u0641\\u064A\\u0646. \\u0631\\u0643\\u0632 \\u0639\\u0648\\u0627\\u062D\\u062F."
t["Two targets. Recover spacing."] = "\\u0647\\u062F\\u0641\\u064A\\u0646. \\u0631\\u062C\\u0639 \\u0627\\u0644\\u0645\\u0633\\u0627\\u0641\\u0629."
t["Two usable nails, please. Then this job can stop waiting."] = "\\u0628\\u0633\\u0645\\u0627\\u0631\\u064A\\u0646 \\u0635\\u0627\\u0644\\u062D\\u064A\\u0646\\u060C \\u0627\\u0644\\u0644\\u0647 \\u064A\\u062E\\u0644\\u064A\\u0643. \\u062E\\u0644\\u0651\\u064A \\u0647\\u0627\\u0644\\u0634\\u063A\\u0644\\u0629 \\u062A\\u062A\\u062D\\u0631\\u0643."
t["Two walkers, close together."] = "\\u062A\\u0646\\u064A\\u0646 \\u0632\\u0648\\u0645\\u0628\\u064A, \\u0644\\u0627\\u0632\\u0642\\u064A\\u0646 \\u0628\\u0628\\u0639\\u0636."
t["Two walkers. Keep them separated!"] = "\\u062A\\u0646\\u064A\\u0646 \\u0632\\u0648\\u0645\\u0628\\u064A. \\u062E\\u0644\\u064A\\u0647\\u0646 \\u0628\\u0639\\u0627\\u062F \\u0639\\u0646 \\u0628\\u0639\\u0636!"
t["Two walkers. Pick one and commit!"] = "\\u062A\\u0646\\u064A\\u0646 \\u0632\\u0648\\u0645\\u0628\\u064A. \\u0646\\u0642\\u064A \\u0648\\u0627\\u062D\\u062F \\u0648\\u062E\\u0644\\u0635!"
t["Two! Stay where I can see you!"] = "\\u062A\\u0646\\u064A\\u0646! \\u062E\\u0644\\u064A\\u0643 \\u0648\\u064A\\u0646 \\u0634\\u0627\\u064A\\u0641\\u062A\\u0643!"
t["Two-step time! Keep them apart!"] = "\\u062F\\u0628\\u0643\\u0629 \\u062A\\u0646\\u064A\\u0646! \\u062E\\u0644\\u064A\\u0647\\u0646 \\u0628\\u0639\\u0627\\u062F \\u0639\\u0646 \\u0628\\u0639\\u0636!"
t["Two? Now it's a fair fight!"] = "\\u062A\\u0646\\u064A\\u0646? \\u0647\\u0644\\u0623 \\u0635\\u0627\\u0631\\u062A \\u0639\\u0627\\u062F\\u0644\\u0629!"
t["Ugly climb, good ending."] = "\\u0637\\u0644\\u0639\\u0629 \\u0628\\u0634\\u0639\\u0629, \\u0648\\u0646\\u0647\\u0627\\u064A\\u0629 \\u062D\\u0644\\u0648\\u0629."
t["Understood. I hope you make it."] = "\\u0645\\u0641\\u0647\\u0648\\u0645. \\u0625\\u0646 \\u0634\\u0627\\u0621 \\u0627\\u0644\\u0644\\u0647 \\u062A\\u0648\\u0635\\u0644 \\u0628\\u0627\\u0644\\u0633\\u0644\\u0627\\u0645\\u0629."
t["Understood. I'll find somewhere defensible."] = "\\u0645\\u0641\\u0647\\u0648\\u0645. \\u0628\\u0644\\u0627\\u0642\\u064A \\u0645\\u062D\\u0644 \\u0628\\u064A\\u0646\\u062D\\u0645\\u0649."
t["Understood. I'll take only what is mine."] = "\\u0645\\u0641\\u0647\\u0648\\u0645. \\u0628\\u0627\\u062E\\u062F \\u0628\\u0633 \\u0627\\u0644\\u0644\\u064A \\u0625\\u0644\\u064A."
t["Unidentified sound, close by. Stay alert."] = "\\u0635\\u0648\\u062A \\u0645\\u0648 \\u0645\\u0639\\u0631\\u0648\\u0641\\u060C \\u0642\\u0631\\u064A\\u0628. \\u062E\\u0644\\u064A\\u0643 \\u0645\\u0646\\u062A\\u0628\\u0647."
t["Until this is settled, I make the calls."] = "\\u0644\\u064A\\u0646\\u062D\\u0633\\u0645 \\u0647\\u0627\\u0644\\u0645\\u0648\\u0636\\u0648\\u0639\\u060C \\u0623\\u0646\\u0627 \\u0627\\u0644\\u0644\\u064A \\u0628\\u0642\\u0631\\u0631."
t["Up and clear. Thanks."] = "\\u0642\\u0645\\u062A \\u0648\\u0627\\u0644\\u0645\\u0643\\u0627\\u0646 \\u0646\\u0636\\u064A\\u0641. \\u0634\\u0643\\u0631\\u0627."
t["Up high, my brain whispers ideas. My legs veto them."] = "\\u0628\\u0627\\u0644\\u0639\\u0627\\u0644\\u064A \\u0639\\u0642\\u0644\\u064A \\u0628\\u064A\\u0648\\u0634\\u0648\\u0634 \\u0623\\u0641\\u0643\\u0627\\u0631. \\u0631\\u062C\\u0644\\u064A\\u064A \\u0628\\u062A\\u0639\\u062A\\u0631\\u0636."
t["Up. Keeping my distance now."] = "\\u0642\\u0645\\u062A. \\u0647\\u0644\\u0623 \\u0639\\u0645 \\u062E\\u0644\\u064A \\u0645\\u0633\\u0627\\u0641\\u0629."
t["Up. Watch the flanks this time."] = "\\u0642\\u0645\\u062A. \\u0627\\u0646\\u062A\\u0628\\u0647 \\u0644\\u0644\\u062C\\u0646\\u0627\\u0628 \\u0647\\u0627\\u0644\\u0645\\u0631\\u0629."
t["Urge to buy a lottery ticket. The odds have never been better."] = "\\u062C\\u0627\\u064A \\u0639\\u0628\\u0627\\u0644\\u064A \\u0627\\u0634\\u062A\\u0631\\u064A \\u0648\\u0631\\u0642\\u0629 \\u064A\\u0627\\u0646\\u0635\\u064A\\u0628. \\u0639\\u0645\\u0631\\u0647\\u0627 \\u0627\\u0644\\u0641\\u0631\\u0635\\u0629 \\u0645\\u0627 \\u0643\\u0627\\u0646\\u062A \\u0623\\u062D\\u0633\\u0646."
t["Urge to challenge the next one to arm wrestling. I'd kick its ass."] = "\\u0631\\u063A\\u0628\\u0629 \\u0627\\u062A\\u062D\\u062F\\u0649 \\u0627\\u0644\\u062C\\u0627\\u064A \\u0628\\u0644\\u064A \\u0625\\u064A\\u062F. \\u0648\\u0628\\u0645\\u0633\\u062D \\u0641\\u064A\\u0647 \\u0627\\u0644\\u0623\\u0631\\u0636."
t["Urge to challenge the next one to arm wrestling. I'd win."] = "\\u0631\\u063A\\u0628\\u0629 \\u0627\\u062A\\u062D\\u062F\\u0649 \\u0627\\u0644\\u062C\\u0627\\u064A \\u0628\\u0644\\u064A \\u0625\\u064A\\u062F. \\u0648\\u0628\\u0631\\u0628\\u062D."
t["Urge to grab the wheel. Just a little. I'm sitting on my hands."] = "\\u0631\\u063A\\u0628\\u0629 \\u0627\\u0645\\u0633\\u0643 \\u0627\\u0644\\u062F\\u0631\\u0643\\u0633\\u064A\\u0648\\u0646. \\u0634\\u0648\\u064A \\u0628\\u0633. \\u0639\\u0645 \\u0627\\u0642\\u0639\\u062F \\u0639\\u0644\\u0649 \\u0625\\u064A\\u062F\\u064A\\u064A."
t["Urge to knock on the wall to see if anything knocks back. No."] = "\\u0631\\u063A\\u0628\\u0629 \\u0627\\u062F\\u0642 \\u0639\\u0627\\u0644\\u062D\\u064A\\u0637 \\u0644\\u0634\\u0648\\u0641 \\u0625\\u0630\\u0627 \\u0634\\u064A \\u0628\\u064A\\u0631\\u062F. \\u0644\\u0623."
t["Urge to open every drawer. No. Absolutely not."] = "\\u0631\\u063A\\u0628\\u0629 \\u0627\\u0641\\u062A\\u062D \\u0643\\u0644 \\u0627\\u0644\\u062C\\u0648\\u0627\\u0631\\u064A\\u0631. \\u0644\\u0623. \\u0645\\u0633\\u062A\\u062D\\u064A\\u0644."
t["Urge to order a drink from nobody. Tipping well."] = "\\u062C\\u0627\\u064A \\u0639\\u0628\\u0627\\u0644\\u064A \\u0627\\u0637\\u0644\\u0628 \\u0643\\u0627\\u0633 \\u0645\\u0646 \\u0648\\u0644\\u0627 \\u062D\\u062F\\u0627. \\u0648\\u0628\\u062F\\u0641\\u0639 \\u0628\\u062E\\u0634\\u064A\\u0634 \\u0645\\u062D\\u0631\\u0632."
t["Urge to order a kids meal. Toy included."] = "\\u062C\\u0627\\u064A \\u0639\\u0628\\u0627\\u0644\\u064A \\u0627\\u0637\\u0644\\u0628 \\u0648\\u062C\\u0628\\u0629 \\u0648\\u0644\\u0627\\u062F. \\u0645\\u0639 \\u0627\\u0644\\u0647\\u062F\\u064A\\u0629 \\u0637\\u0628\\u0639\\u0627\\u064B."
t["Urge to read every label. Side effects may include everything."] = "\\u062C\\u0627\\u064A \\u0639\\u0628\\u0627\\u0644\\u064A \\u0627\\u0642\\u0631\\u0627 \\u0643\\u0644 \\u0627\\u0644\\u0646\\u0634\\u0631\\u0627\\u062A. \\u0627\\u0644\\u0623\\u0639\\u0631\\u0627\\u0636 \\u0627\\u0644\\u062C\\u0627\\u0646\\u0628\\u064A\\u0629: \\u0643\\u0644 \\u0634\\u064A."
t["Urge to ring the bell. Everyone would come. That's the problem."] = "\\u0631\\u063A\\u0628\\u0629 \\u0627\\u062F\\u0642 \\u0627\\u0644\\u062C\\u0631\\u0633. \\u0627\\u0644\\u0643\\u0644 \\u0631\\u062D \\u064A\\u062C\\u0648\\u0627. \\u0647\\u064A \\u0627\\u0644\\u0645\\u0634\\u0643\\u0644\\u0629."
t["Urge to skip. Full skipping. I am suppressing it professionally."] = "\\u0631\\u063A\\u0628\\u0629 \\u0628\\u0627\\u0644\\u0646\\u0637. \\u0646\\u0637 \\u0643\\u0627\\u0645\\u0644. \\u0639\\u0645 \\u0627\\u0643\\u0628\\u062A\\u0647\\u0627 \\u0628\\u0627\\u062D\\u062A\\u0631\\u0627\\u0641."
t["Urge to sleep on the roof. Under the stars. Armed."] = "\\u0631\\u063A\\u0628\\u0629 \\u0646\\u0627\\u0645 \\u0639\\u0627\\u0644\\u0633\\u0637\\u062D. \\u062A\\u062D\\u062A \\u0627\\u0644\\u0646\\u062C\\u0648\\u0645. \\u0645\\u0633\\u0644\\u062D\\u0629."
t["Use one round. Make it certain."] = "\\u0631\\u0635\\u0627\\u0635\\u0629 \\u0648\\u062D\\u062F\\u0629. \\u062A\\u0643\\u0648\\u0646 \\u0623\\u0643\\u064A\\u062F\\u0629."
t["Use the route we marked. Go now."] = "\\u062E\\u062F \\u0627\\u0644\\u0637\\u0631\\u064A\\u0642 \\u0627\\u0644\\u0644\\u064A \\u0639\\u0644\\u0645\\u0646\\u0627\\u0647. \\u0631\\u0648\\u062D \\u0647\\u0644\\u0623."
t["Used to think somebody would come for us. Now I just fix things."] = "\\u0643\\u0646\\u062A \\u0641\\u0643\\u0631 \\u062D\\u062F\\u0627 \\u0631\\u062D \\u064A\\u062C\\u064A \\u064A\\u0627\\u062E\\u062F\\u0646\\u0627. \\u0647\\u0644\\u0623 \\u0628\\u0633 \\u0628\\u0635\\u0644\\u0651\\u062D \\u0634\\u063A\\u0644\\u0627\\u062A."
t["Useful knowledge should outlive the person who found it."] = "\\u0627\\u0644\\u0645\\u0639\\u0631\\u0641\\u0629 \\u0627\\u0644\\u0645\\u0641\\u064A\\u062F\\u0629 \\u0644\\u0627\\u0632\\u0645 \\u062A\\u0639\\u064A\\u0634 \\u0623\\u0643\\u062A\\u0631 \\u0645\\u0646 \\u0627\\u0644\\u0644\\u064A \\u0644\\u0642\\u0627\\u0647\\u0627."
t["Useful method. I will remember the order of steps."] = "\\u0637\\u0631\\u064A\\u0642\\u0629 \\u0645\\u0641\\u064A\\u062F\\u0629. \\u0631\\u062D \\u0627\\u062D\\u0641\\u0638 \\u062A\\u0631\\u062A\\u064A\\u0628 \\u0627\\u0644\\u062E\\u0637\\u0648\\u0627\\u062A."
t["Useful, if we have the right tools and a safe place."] = "\\u0645\\u0641\\u064A\\u062F\\u060C \\u0625\\u0630\\u0627 \\u0643\\u0627\\u0646 \\u0639\\u0646\\u0627 \\u0627\\u0644\\u0639\\u062F\\u0629 \\u0648\\u0645\\u062D\\u0644 \\u0622\\u0645\\u0646."
t["Vats of beer and nobody to drink them. The real tragedy of the Knox Event."] = "\\u062E\\u0632\\u0627\\u0646\\u0627\\u062A \\u0628\\u064A\\u0631\\u0629 \\u0648\\u0645\\u0627 \\u0641\\u064A \\u062D\\u062F\\u0627 \\u064A\\u0634\\u0631\\u0628\\u0647\\u0627. \\u0647\\u064A \\u0627\\u0644\\u0645\\u0623\\u0633\\u0627\\u0629 \\u0627\\u0644\\u062D\\u0642\\u064A\\u0642\\u064A\\u0629 \\u0644\\u062D\\u0627\\u062F\\u062B\\u0629 \\u0646\\u0648\\u0643\\u0633."
t["Vehicle remains stationary. Strong performance so far."] = "\\u0627\\u0644\\u0633\\u064A\\u0627\\u0631\\u0629 \\u0644\\u0633\\u0627 \\u0648\\u0627\\u0642\\u0641\\u0629. \\u0623\\u062F\\u0627\\u0621 \\u0642\\u0648\\u064A \\u0644\\u0647\\u0644\\u0623."
t["Visibility is going. Let's keep the spacing tight."] = "\\u0627\\u0644\\u0631\\u0624\\u064A\\u0629 \\u0639\\u0645 \\u062A\\u0631\\u0648\\u062D. \\u062E\\u0644\\u064A\\u0646\\u0627 \\u0646\\u0642\\u0631\\u0628 \\u0645\\u0646 \\u0628\\u0639\\u0636."
t["Visibility's poor. I want a clear retreat line."] = "\\u0627\\u0644\\u0631\\u0624\\u064A\\u0629 \\u0636\\u0639\\u064A\\u0641\\u0629. \\u0628\\u062F\\u064A \\u062E\\u0637 \\u0627\\u0646\\u0633\\u062D\\u0627\\u0628 \\u0648\\u0627\\u0636\\u062D."
t["Visiting hours are over!"] = "\\u062E\\u0644\\u0635\\u062A \\u0633\\u0627\\u0639\\u0627\\u062A \\u0627\\u0644\\u0632\\u064A\\u0627\\u0631\\u0629!"
t["Visiting hours are over. Permanently."] = "\\u0627\\u0646\\u062A\\u0647\\u062A \\u0627\\u0644\\u0632\\u064A\\u0627\\u0631\\u0629. \\u0644\\u0644\\u0623\\u0628\\u062F."
t["Wait, turn that up. I want to catch the next step."] = "\\u0627\\u0633\\u062A\\u0646\\u0649\\u060C \\u0639\\u0644\\u0651\\u064A \\u0627\\u0644\\u0635\\u0648\\u062A. \\u0628\\u062F\\u064A \\u0627\\u0644\\u062D\\u0642 \\u0627\\u0644\\u062E\\u0637\\u0648\\u0629 \\u0627\\u0644\\u062C\\u0627\\u064A\\u0629."
t["Wait. That part might help us."] = "\\u0627\\u0633\\u062A\\u0646\\u0649. \\u0647\\u0627\\u0644\\u0642\\u0633\\u0645 \\u064A\\u0645\\u0643\\u0646 \\u064A\\u0641\\u064A\\u062F\\u0646\\u0627."
t["Waiting gives every bad possibility time to grow."] = "\\u0627\\u0644\\u0627\\u0646\\u062A\\u0638\\u0627\\u0631 \\u0628\\u064A\\u0639\\u0637\\u064A \\u0643\\u0644 \\u0627\\u062D\\u062A\\u0645\\u0627\\u0644 \\u0639\\u0627\\u0637\\u0644 \\u0648\\u0642\\u062A \\u064A\\u0643\\u0628\\u0631."
t["Waiting room magazines. Everyone here was waiting for something."] = "\\u0645\\u062C\\u0644\\u0627\\u062A \\u063A\\u0631\\u0641\\u0629 \\u0627\\u0644\\u0627\\u0646\\u062A\\u0638\\u0627\\u0631. \\u0627\\u0644\\u0643\\u0644 \\u0647\\u0648\\u0646 \\u0643\\u0627\\u0646 \\u0645\\u0633\\u062A\\u0646\\u064A \\u0634\\u064A."
t["Waiting's a skill too. You're maxing it out."] = "\\u0627\\u0644\\u0627\\u0646\\u062A\\u0638\\u0627\\u0631 \\u0645\\u0647\\u0627\\u0631\\u0629 \\u0643\\u0645\\u0627\\u0646. \\u0648\\u0625\\u0646\\u062A \\u0648\\u0635\\u0644\\u062A \\u0641\\u064A\\u0647\\u0627 \\u0644\\u0644\\u0642\\u0645\\u0629."
t["Wake me when waiting becomes a profession. I'd qualify."] = "\\u0641\\u064A\\u0651\\u0642\\u0646\\u064A \\u0644\\u0645\\u0627 \\u064A\\u0635\\u064A\\u0631 \\u0627\\u0644\\u0627\\u0646\\u062A\\u0638\\u0627\\u0631 \\u0645\\u0647\\u0646\\u0629. \\u0639\\u0646\\u062F\\u064A \\u0627\\u0644\\u062E\\u0628\\u0631\\u0629."
t["Walk with me a second. Away from the others."] = "\\u0627\\u0645\\u0634\\u064A \\u0645\\u0639\\u064A \\u0634\\u0648\\u064A. \\u0628\\u0639\\u064A\\u062F \\u0639\\u0646 \\u0627\\u0644\\u0628\\u0627\\u0642\\u064A\\u064A\\u0646."
t["Walker heard nearby. Position uncertain."] = "\\u0641\\u064A \\u0632\\u0648\\u0645\\u0628\\u064A \\u0642\\u0631\\u064A\\u0628 \\u0628\\u0627\\u0644\\u0635\\u0648\\u062A. \\u0645\\u0643\\u0627\\u0646\\u0647 \\u0645\\u0648 \\u0648\\u0627\\u0636\\u062D."
t["Walker nearby. We wait until we see it."] = "\\u0641\\u064A \\u0632\\u0648\\u0645\\u0628\\u064A \\u0642\\u0631\\u064A\\u0628. \\u0645\\u0646\\u0633\\u062A\\u0646\\u0649 \\u0644\\u0646\\u0634\\u0648\\u0641\\u0647."
t["Walker sitting against the wall. Watch it."] = "\\u0641\\u064A \\u0648\\u0627\\u062D\\u062F \\u0642\\u0627\\u0639\\u062F \\u0639\\u0627\\u0644\\u062D\\u064A\\u0637. \\u0627\\u0646\\u062A\\u0628\\u0647."
t["Walker! Right there!"] = "\\u0648\\u0627\\u062D\\u062F \\u0645\\u0646\\u0647\\u0645! \\u0647\\u0648\\u0646\\u064A\\u0643!"
t["Walking together beats walking alone. Even now."] = "\\u0627\\u0644\\u0645\\u0634\\u064A \\u0633\\u0648\\u0627 \\u0623\\u062D\\u0633\\u0646 \\u0645\\u0646 \\u0627\\u0644\\u0645\\u0634\\u064A \\u0644\\u062D\\u0627\\u0644. \\u062D\\u062A\\u0649 \\u0647\\u0644\\u0623."
t["Wall crossed. Could have been less graceful."] = "\\u0642\\u0637\\u0639\\u062A \\u0627\\u0644\\u062D\\u064A\\u0637. \\u0643\\u0627\\u0646 \\u0645\\u0645\\u0643\\u0646 \\u064A\\u0643\\u0648\\u0646 \\u0623\\u0628\\u0634\\u0639."
t["Wall crossed. Route is open."] = "\\u0642\\u0637\\u0639\\u062A \\u0627\\u0644\\u062D\\u064A\\u0637. \\u0627\\u0644\\u0637\\u0631\\u064A\\u0642 \\u0633\\u0627\\u0644\\u0643."
t["Walls this close turn one mistake into a grave."] = "\\u062D\\u064A\\u0637\\u0627\\u0646 \\u0642\\u0631\\u064A\\u0628\\u0629 \\u0647\\u064A\\u0643 \\u0628\\u062A\\u0642\\u0644\\u0628 \\u0627\\u0644\\u063A\\u0644\\u0637\\u0629 \\u0627\\u0644\\u0648\\u062D\\u062F\\u0629 \\u0644\\u0642\\u0628\\u0631."
t["Walls up, shelves full. Let the world try us now."] = "\\u0627\\u0644\\u062D\\u064A\\u0637\\u0627\\u0646 \\u0637\\u0627\\u0644\\u0639\\u0629 \\u0648\\u0627\\u0644\\u0631\\u0641\\u0648\\u0641 \\u0645\\u0644\\u064A\\u0627\\u0646\\u0629. \\u062E\\u0644\\u064A \\u0627\\u0644\\u062F\\u0646\\u064A\\u0627 \\u062A\\u062C\\u0631\\u0628\\u0646\\u0627 \\u0647\\u0644\\u0623."
t["Wanted posters. Most of these fellas are walking around dead now. Still wanted."] = "\\u0635\\u0648\\u0631 \\u0645\\u0637\\u0644\\u0648\\u0628\\u064A\\u0646. \\u0623\\u063A\\u0644\\u0628\\u0647\\u0645 \\u0647\\u0644\\u0623 \\u0645\\u0627\\u0634\\u064A\\u064A\\u0646 \\u0645\\u064A\\u062A\\u064A\\u0646. \\u0648\\u0644\\u0633\\u0627 \\u0645\\u0637\\u0644\\u0648\\u0628\\u064A\\u0646."
t["Warm beer is still beer. Don't let anybody tell you different."] = "\\u0627\\u0644\\u0628\\u064A\\u0631\\u0629 \\u0627\\u0644\\u0633\\u062E\\u0646\\u0629 \\u0644\\u0633\\u0627 \\u0628\\u064A\\u0631\\u0629. \\u0644\\u0627 \\u062A\\u062E\\u0644\\u064A \\u062D\\u062F\\u0627 \\u064A\\u0642\\u0644\\u0643 \\u063A\\u064A\\u0631 \\u0647\\u064A\\u0643."
t["Warm socks. Clean socks. I could cry."] = "\\u0643\\u0644\\u0633\\u0627\\u062A \\u062F\\u0627\\u0641\\u064A\\u0629. \\u0643\\u0644\\u0633\\u0627\\u062A \\u0646\\u0636\\u064A\\u0641\\u0629. \\u0628\\u062F\\u064A \\u0627\\u0628\\u0643\\u064A."
t["Was it always this quiet in here? It was. Probably."] = "\\u0643\\u0627\\u0646 \\u062F\\u0627\\u064A\\u0645\\u064B\\u0627 \\u0647\\u064A\\u0643 \\u0647\\u0627\\u062F\\u064A \\u0647\\u0648\\u0646\\u061F \\u0643\\u0627\\u0646. \\u063A\\u0627\\u0644\\u0628\\u064B\\u0627."
t["Wash the mud away, leave the memory on..."] = "\\u0627\\u063A\\u0633\\u0644 \\u0627\\u0644\\u0648\\u062D\\u0644 \\u0648\\u062E\\u0644\\u064A \\u0627\\u0644\\u0630\\u0643\\u0631\\u0649..."
t["Watch it. I don't want to get hurt by you."] = "\\u0627\\u0646\\u062A\\u0628\\u0647. \\u0645\\u0627 \\u0628\\u062F\\u064A \\u0627\\u0646\\u0635\\u0627\\u0628 \\u0645\\u0646\\u0643."
t["Watch the backswing, will you?"] = "\\u0627\\u0646\\u062A\\u0628\\u0647 \\u0644\\u0645\\u0627 \\u062A\\u0631\\u062C\\u0639 \\u0625\\u064A\\u062F\\u0643\\u060C \\u0645\\u0645\\u0643\\u0646\\u061F"
t["Watch the corners. They don't announce themselves."] = "\\u0627\\u0646\\u062A\\u0628\\u0647 \\u0639\\u0627\\u0644\\u0632\\u0648\\u0627\\u064A\\u0627. \\u0645\\u0627 \\u0628\\u064A\\u0639\\u0637\\u0648\\u0627 \\u062E\\u0628\\u0631."
t["Watch the seated one. It can reach from there."] = "\\u0627\\u0646\\u062A\\u0628\\u0647 \\u0644\\u0644\\u0642\\u0627\\u0639\\u062F. \\u0628\\u062A\\u0648\\u0635\\u0644\\u0643 \\u0625\\u064A\\u062F\\u0647 \\u0645\\u0646 \\u0647\\u0648\\u0646\\u064A\\u0643."
t["Watch the side street at %1."] = "\\u0627\\u0646\\u062A\\u0628\\u0647 \\u0644\\u0644\\u0634\\u0627\\u0631\\u0639 \\u0627\\u0644\\u062C\\u0627\\u0646\\u0628\\u064A \\u0639\\u0646\\u062F %1."
t["Watch where you point that thing!"] = "\\u0627\\u0646\\u062A\\u0628\\u0647 \\u0648\\u064A\\u0646 \\u0639\\u0645 \\u062A\\u0648\\u062C\\u0647 \\u0647\\u0627\\u0644\\u0634\\u064A!"
t["Watch yourself! Zombie!"] = "\\u062F\\u064A\\u0631 \\u0628\\u0627\\u0644\\u0643! \\u0632\\u0648\\u0645\\u0628\\u064A!"
t["Water at the next stop, for all of us if we can."] = "\\u0645\\u064A \\u0628\\u0627\\u0644\\u0648\\u0642\\u0641\\u0629 \\u0627\\u0644\\u062C\\u0627\\u064A\\u0629\\u060C \\u0644\\u0644\\u0643\\u0644 \\u0625\\u0630\\u0627 \\u0641\\u064A\\u0646\\u0627."
t["Water first. Everything else waits if the cans are empty."] = "\\u0627\\u0644\\u0645\\u064A \\u0623\\u0648\\u0644. \\u0643\\u0644 \\u0634\\u064A \\u0628\\u064A\\u0633\\u062A\\u0646\\u0649 \\u0625\\u0630\\u0627 \\u0627\\u0644\\u062A\\u0646\\u0643\\u0627\\u062A \\u0641\\u0627\\u0636\\u064A\\u0629."
t["Water has to become a priority."] = "\\u0627\\u0644\\u0645\\u064A \\u0644\\u0627\\u0632\\u0645 \\u062A\\u0635\\u064A\\u0631 \\u0623\\u0648\\u0644\\u0648\\u064A\\u0629."
t["Water is my first priority right now."] = "\\u0627\\u0644\\u0645\\u064A \\u0623\\u0648\\u0644 \\u0634\\u064A \\u0647\\u0644\\u0623."
t["Water level is low. Correcting it."] = "\\u0627\\u0644\\u0645\\u064A \\u0642\\u0644\\u064A\\u0644\\u0629. \\u0639\\u0645 \\u0635\\u0644\\u0651\\u062D\\u0647\\u0627."
t["Water looks calm enough. Let us see what bites."] = "\\u0627\\u0644\\u0645\\u064A \\u0647\\u0627\\u062F\\u064A\\u0629 \\u0643\\u0641\\u0627\\u064A\\u0629. \\u062E\\u0644\\u064A\\u0646\\u0627 \\u0646\\u0634\\u0648\\u0641 \\u0634\\u0648 \\u0628\\u064A\\u0639\\u0644\\u0642."
t["Water need is rising, not critical yet."] = "\\u0627\\u0644\\u062D\\u0627\\u062C\\u0629 \\u0644\\u0644\\u0645\\u064A \\u0639\\u0645 \\u062A\\u0632\\u064A\\u062F\\u060C \\u0644\\u0633\\u0627 \\u0645\\u0648 \\u062E\\u0637\\u0631."
t["Water towers and church steeples make decent landmarks."] = "\\u062E\\u0632\\u0627\\u0646\\u0627\\u062A \\u0627\\u0644\\u0645\\u064A \\u0648\\u0645\\u0646\\u0627\\u0631\\u0627\\u062A \\u0627\\u0644\\u0643\\u0646\\u0627\\u064A\\u0633 \\u0639\\u0644\\u0627\\u0645\\u0627\\u062A \\u0645\\u0646\\u064A\\u062D\\u0629."
t["Water, if we can spare it. I am getting very thirsty."] = "\\u0645\\u064A\\u060C \\u0625\\u0630\\u0627 \\u0641\\u064A\\u0646\\u0627 \\u0646\\u0633\\u062A\\u063A\\u0646\\u064A \\u0639\\u0646\\u0647\\u0627. \\u0639\\u0637\\u0634\\u0627\\u0646\\u0629 \\u0643\\u062A\\u064A\\u0631."
t["Water, please. Anything clean."] = "\\u0645\\u064A\\u060C \\u0627\\u0644\\u0644\\u0647 \\u064A\\u062E\\u0644\\u064A\\u0643. \\u0623\\u064A \\u0634\\u064A \\u0646\\u0636\\u064A\\u0641."
t["Watering. The plants are the quietest mouths here."] = "\\u0639\\u0645 \\u0627\\u0633\\u0642\\u064A. \\u0627\\u0644\\u0632\\u0631\\u0639 \\u0623\\u0647\\u062F\\u0649 \\u0627\\u0644\\u062A\\u0645\\u0627\\u0645 \\u0628\\u0647\\u0627\\u0644\\u0645\\u062D\\u0644."
t["We agreed on the plan, and then you changed it!"] = "\\u0627\\u062A\\u0641\\u0642\\u0646\\u0627 \\u0639\\u0627\\u0644\\u062E\\u0637\\u0629\\u060C \\u0648\\u0625\\u0646\\u062A \\u063A\\u064A\\u0631\\u062A\\u0647\\u0627!"
t["We are %1. Supplies are %2."] = "\\u0646\\u062D\\u0646\\u0627 %1. \\u0648\\u0627\\u0644\\u0645\\u0648\\u0646\\u0629 %2."
t["We are doing well because we watch out for each other."] = "\\u0648\\u0636\\u0639\\u0646\\u0627 \\u0645\\u0646\\u064A\\u062D \\u0644\\u0623\\u0646 \\u0643\\u0644 \\u0648\\u0627\\u062D\\u062F \\u0645\\u0646\\u0627 \\u0633\\u0646\\u062F \\u0627\\u0644\\u062A\\u0627\\u0646\\u064A."
t["We are mourning %1. Business can wait unless it is urgent."] = "\\u0639\\u0645 \\u0646\\u062D\\u0632\\u0646 \\u0639\\u0644\\u0649 %1. \\u0627\\u0644\\u0634\\u063A\\u0644 \\u0628\\u064A\\u0633\\u062A\\u0646\\u0649 \\u0625\\u0644\\u0627 \\u0625\\u0630\\u0627 \\u0645\\u0633\\u062A\\u0639\\u062C\\u0644."
t["We are not enemies. The rest still has to be earned."] = "\\u0645\\u0648 \\u0623\\u0639\\u062F\\u0627\\u0621. \\u0648\\u0627\\u0644\\u0628\\u0627\\u0642\\u064A \\u0644\\u0633\\u0627 \\u0628\\u062F\\u0643 \\u062A\\u0633\\u062A\\u0627\\u0647\\u0644\\u0647."
t["We are pushing our luck. I want a clear way out before we go farther."] = "\\u0639\\u0645 \\u0646\\u0639\\u0627\\u0646\\u062F \\u0627\\u0644\\u062D\\u0638. \\u0628\\u062F\\u064A \\u0637\\u0631\\u064A\\u0642 \\u0647\\u0631\\u0648\\u0628 \\u0642\\u0628\\u0644 \\u0645\\u0627 \\u0646\\u0643\\u0641\\u0651\\u064A."
t["We are running out of %1."] = "\\u0639\\u0645 \\u064A\\u062E\\u0644\\u0635 \\u0639\\u0646\\u0627 %1."
t["We are safe for a moment. Let me check on everyone."] = "\\u0628\\u0623\\u0645\\u0627\\u0646 \\u0644\\u0644\\u062D\\u0638\\u0629. \\u062E\\u0644\\u064A\\u0646\\u064A \\u0627\\u062A\\u0637\\u0645\\u0646 \\u0639\\u0627\\u0644\\u0643\\u0644."
t["We are still here. Today, that has to be enough."] = "\\u0644\\u0633\\u0627 \\u0647\\u0648\\u0646. \\u0627\\u0644\\u064A\\u0648\\u0645\\u060C \\u0647\\u0627\\u062F \\u0644\\u0627\\u0632\\u0645 \\u064A\\u0643\\u0641\\u064A."
t["We are still learning each other, but I trust you more than I did."] = "\\u0644\\u0633\\u0627 \\u0639\\u0645 \\u0646\\u062A\\u0639\\u0631\\u0641 \\u0639\\u0644\\u0649 \\u0628\\u0639\\u0636\\u060C \\u0628\\u0633 \\u0635\\u0631\\u062A \\u0648\\u0627\\u062B\\u0642\\u0629 \\u0641\\u064A\\u0643 \\u0623\\u0643\\u062A\\u0631 \\u0645\\u0646 \\u0642\\u0628\\u0644."
t["We are taking risks faster than I can swallow them."] = "\\u0639\\u0645 \\u0646\\u062E\\u0627\\u0637\\u0631 \\u0623\\u0633\\u0631\\u0639 \\u0645\\u0627 \\u0628\\u0642\\u062F\\u0631 \\u0628\\u0644\\u0639."
t["We are turning this place into something worth defending."] = "\\u0639\\u0645 \\u0646\\u062E\\u0644\\u064A \\u0647\\u0627\\u0644\\u0645\\u062D\\u0644 \\u0634\\u064A \\u0628\\u064A\\u0633\\u062A\\u0627\\u0647\\u0644 \\u0646\\u062F\\u0627\\u0641\\u0639 \\u0639\\u0646\\u0647."
t["We are wasting energy making the same mistakes."] = "\\u0639\\u0645 \\u0646\\u0636\\u064A\\u0651\\u0639 \\u0637\\u0627\\u0642\\u062A\\u0646\\u0627 \\u0628\\u0646\\u0641\\u0633 \\u0627\\u0644\\u063A\\u0644\\u0637\\u0627\\u062A."
t["We argued about seats too. Nobody wanted the wobbly chair."] = "\\u0646\\u062D\\u0646\\u0627 \\u0643\\u0645\\u0627\\u0646 \\u0643\\u0646\\u0627 \\u0646\\u062A\\u062E\\u0627\\u0646\\u0642 \\u0639\\u0627\\u0644\\u0643\\u0631\\u0627\\u0633\\u064A. \\u0645\\u0627 \\u062D\\u062F\\u0627 \\u0628\\u062F\\u0648 \\u0627\\u0644\\u0643\\u0631\\u0633\\u064A \\u0627\\u0644\\u062E\\u0631\\u0628\\u0627\\u0646."
t["We barely had time to know each other, %1. I'm sorry it ends here."] = "\\u0645\\u0627 \\u0644\\u062D\\u0642\\u0646\\u0627 \\u0646\\u0639\\u0631\\u0641 \\u0628\\u0639\\u0636 \\u064A\\u0627 %1. \\u0622\\u0633\\u0641\\u0629 \\u062E\\u0644\\u0635\\u062A \\u0647\\u0648\\u0646."
t["We beat the dead and the weather. Harvest time."] = "\\u063A\\u0644\\u0628\\u0646\\u0627 \\u0627\\u0644\\u0645\\u0648\\u062A\\u0649 \\u0648\\u0627\\u0644\\u0637\\u0642\\u0633. \\u0648\\u0642\\u062A \\u0627\\u0644\\u062D\\u0635\\u0627\\u062F."
t["We came this far for %1?"] = "\\u0643\\u0644 \\u0647\\u0627\\u0644\\u0637\\u0631\\u064A\\u0642 \\u0645\\u0634\\u0627\\u0646 %1?"
t["We can disagree without tearing each other apart."] = "\\u0641\\u064A\\u0646\\u0627 \\u0646\\u062E\\u062A\\u0644\\u0641 \\u0628\\u0644\\u0627 \\u0645\\u0627 \\u0646\\u0627\\u0643\\u0644 \\u0628\\u0639\\u0636."
t["We can do one job at a time. That's how we got this far."] = "\\u0645\\u0646\\u0639\\u0645\\u0644 \\u0634\\u063A\\u0644\\u0629 \\u0634\\u063A\\u0644\\u0629. \\u0647\\u064A\\u0643 \\u0648\\u0635\\u0644\\u0646\\u0627 \\u0644\\u0647\\u0648\\u0646."
t["We can fix the plan. We cannot fix this by tearing into each other."] = "\\u0645\\u0646\\u0635\\u0644\\u0651\\u062D \\u0627\\u0644\\u062E\\u0637\\u0629. \\u0628\\u0633 \\u0645\\u0627 \\u0645\\u0646\\u0635\\u0644\\u0651\\u062D\\u0647\\u0627 \\u0648\\u0646\\u062D\\u0646\\u0627 \\u0639\\u0645 \\u0646\\u0646\\u0647\\u0634 \\u0628\\u0628\\u0639\\u0636."
t["We can handle a fight, but only if it gets us somewhere."] = "\\u0641\\u064A\\u0646\\u0627 \\u0639\\u0627\\u0644\\u062E\\u0646\\u0627\\u0642\\u0629\\u060C \\u0628\\u0633 \\u0625\\u0630\\u0627 \\u0643\\u0627\\u0646\\u062A \\u0628\\u062A\\u0648\\u0635\\u0644\\u0646\\u0627 \\u0644\\u0634\\u064A."
t["We can handle the next run. Smart and steady."] = "\\u0641\\u064A\\u0646\\u0627 \\u0639\\u0627\\u0644\\u0645\\u0634\\u0648\\u0627\\u0631 \\u0627\\u0644\\u062C\\u0627\\u064A. \\u0628\\u0639\\u0642\\u0644 \\u0648\\u0639\\u0627\\u0644\\u0647\\u062F\\u0627."
t["We can hear you from where you are. Speak."] = "\\u0633\\u0627\\u0645\\u0639\\u064A\\u0646\\u0643 \\u0645\\u0646 \\u0645\\u0637\\u0631\\u062D\\u0643. \\u0627\\u062D\\u0643\\u064A."
t["We can leave this here. Stay back."] = "\\u0641\\u064A\\u0646\\u0627 \\u0646\\u062E\\u0644\\u064A\\u0647\\u0627 \\u0647\\u0648\\u0646. \\u0636\\u0644 \\u0628\\u0639\\u064A\\u062F."
t["We can listen again when the weather clears."] = "\\u0641\\u064A\\u0646\\u0627 \\u0646\\u0631\\u062C\\u0639 \\u0646\\u0633\\u0645\\u0639 \\u0644\\u0645\\u0627 \\u064A\\u0635\\u062D\\u0649 \\u0627\\u0644\\u0637\\u0642\\u0633."
t["We can measure supplies. We still have to decide what enough means."] = "\\u0641\\u064A\\u0646\\u0627 \\u0646\\u0639\\u062F \\u0627\\u0644\\u0645\\u0648\\u0646\\u0629. \\u0628\\u0633 \\u0644\\u0627\\u0632\\u0645 \\u0646\\u0642\\u0631\\u0631 \\u0634\\u0648 \\u064A\\u0639\\u0646\\u064A \\u0628\\u0643\\u0641\\u064A."
t["We can put our boots down without thinking about it."] = "\\u0641\\u064A\\u0646\\u0627 \\u0646\\u062D\\u0637 \\u0628\\u0648\\u0637\\u0646\\u0627 \\u0628\\u0644\\u0627 \\u0645\\u0627 \\u0646\\u0641\\u0643\\u0631."
t["We can read the hard part together if you want."] = "\\u0641\\u064A\\u0646\\u0627 \\u0646\\u0642\\u0631\\u0627 \\u0627\\u0644\\u0642\\u0633\\u0645 \\u0627\\u0644\\u0635\\u0639\\u0628 \\u0633\\u0648\\u0627 \\u0625\\u0630\\u0627 \\u0628\\u062F\\u0643."
