t["We can spare a few minutes to hear the world breathe."] = "\\u0641\\u064A\\u0646\\u0627 \\u0646\\u0648\\u0641\\u0631 \\u0643\\u0645 \\u062F\\u0642\\u064A\\u0642\\u0629 \\u0646\\u0633\\u0645\\u0639 \\u0627\\u0644\\u062F\\u0646\\u064A\\u0627 \\u0639\\u0645 \\u062A\\u062A\\u0646\\u0641\\u0633."
t["We can still stop this. Drop your guard and step away."] = "\\u0644\\u0633\\u0627 \\u0641\\u064A\\u0646\\u0627 \\u0646\\u0648\\u0642\\u0641. \\u0646\\u0632\\u0651\\u0644 \\u0625\\u064A\\u062F\\u0643 \\u0648\\u0627\\u0628\\u0639\\u062F."
t["We can talk here. Do not enter the house."] = "\\u0641\\u064A\\u0646\\u0627 \\u0646\\u062D\\u0643\\u064A \\u0647\\u0648\\u0646. \\u0644\\u0627 \\u062A\\u0641\\u0648\\u062A \\u0639\\u0627\\u0644\\u0628\\u064A\\u062A."
