t["We cannot keep wasting supplies like this."] = "\\u0645\\u0627 \\u0641\\u064A\\u0646\\u0627 \\u0646\\u0636\\u0644 \\u0646\\u0647\\u062F\\u0631 \\u0627\\u0644\\u0645\\u0648\\u0646\\u0629 \\u0647\\u064A\\u0643."
t["We carried each other this far. That matters."] = "\\u0634\\u0644\\u0646\\u0627 \\u0628\\u0639\\u0636 \\u0644\\u0647\\u0648\\u0646. \\u0648\\u0647\\u0627\\u062F \\u0628\\u064A\\u0641\\u0631\\u0642."
