t["We conserve ammunition, keep our tools ready, and choose useful fights."] = "\\u0645\\u0646\\u0648\\u0641\\u0651\\u0631 \\u0627\\u0644\\u0631\\u0635\\u0627\\u0635\\u060C \\u0645\\u0646\\u062C\\u0647\\u0632 \\u0627\\u0644\\u0639\\u062F\\u0629\\u060C \\u0648\\u0645\\u0646\\u062E\\u062A\\u0627\\u0631 \\u0627\\u0644\\u0642\\u062A\\u0627\\u0644 \\u0627\\u0644\\u0644\\u064A \\u0628\\u064A\\u0646\\u0641\\u0639."
t["We could charge admission for this. Nobody would pay."] = "\\u0641\\u064A\\u0646\\u0627 \\u0646\\u0628\\u064A\\u0639 \\u062A\\u0630\\u0627\\u0643\\u0631 \\u0639\\u0644\\u0649 \\u0647\\u0627\\u0644\\u0639\\u0631\\u0636. \\u0645\\u0627 \\u062D\\u062F\\u0627 \\u0631\\u062D \\u064A\\u062F\\u0641\\u0639."
t["We could talk about the old days. I miss complaining about TV."] = "\\u0641\\u064A\\u0646\\u0627 \\u0646\\u062D\\u0643\\u064A \\u0639\\u0646 \\u0627\\u0644\\u0623\\u064A\\u0627\\u0645 \\u0627\\u0644\\u0642\\u062F\\u064A\\u0645\\u0629. \\u0645\\u0634\\u062A\\u0627\\u0642\\u0629 \\u0646\\u0642 \\u0639\\u0627\\u0644\\u062A\\u0644\\u0641\\u0632\\u064A\\u0648\\u0646."
t["We decide this now, before they turn."] = "\\u0645\\u0646\\u0642\\u0631\\u0631 \\u0647\\u0644\\u0623\\u060C \\u0642\\u0628\\u0644 \\u0645\\u0627 \\u064A\\u062A\\u062D\\u0648\\u0644\\u0648\\u0627."
t["We did not have long, %1. Remember that I chose to trust you at the end."] = "\\u0645\\u0627 \\u0643\\u0627\\u0646 \\u0639\\u0646\\u0627 \\u0648\\u0642\\u062A \\u064A\\u0627 %1. \\u062A\\u0630\\u0643\\u0631 \\u0625\\u0646\\u064A \\u0627\\u062E\\u062A\\u0631\\u062A \\u0648\\u062B\\u0642 \\u0641\\u064A\\u0643 \\u0628\\u0627\\u0644\\u0622\\u062E\\u0631."
t["We did not know each other long, %1, but I am glad we met."] = "\\u0645\\u0627 \\u0639\\u0631\\u0641\\u0646\\u0627 \\u0628\\u0639\\u0636 \\u0643\\u062A\\u064A\\u0631 \\u064A\\u0627 %1, \\u0628\\u0633 \\u0645\\u0628\\u0633\\u0648\\u0637\\u0629 \\u0625\\u0646\\u0627 \\u0627\\u0644\\u062A\\u0642\\u064A\\u0646\\u0627."
t["We do not abandon our own. We watch them and keep them safe."] = "\\u0646\\u062D\\u0646\\u0627 \\u0645\\u0627 \\u0645\\u0646\\u062A\\u0631\\u0643 \\u062C\\u0645\\u0627\\u0639\\u062A\\u0646\\u0627. \\u0645\\u0646\\u0631\\u0627\\u0642\\u0628\\u0647\\u0646 \\u0648\\u0645\\u0646\\u062D\\u0645\\u064A\\u0647\\u0646."
t["We don't have enough %1. That's our problem right now."] = "\\u0645\\u0627 \\u0639\\u0646\\u0627 %1 \\u0643\\u0641\\u0627\\u064A\\u0629. \\u0648\\u0647\\u064A \\u0645\\u0634\\u0643\\u0644\\u062A\\u0646\\u0627 \\u0647\\u0644\\u0623."
t["We don't vote on this one. We act."] = "\\u0647\\u064A \\u0645\\u0627 \\u0628\\u062F\\u0647\\u0627 \\u062A\\u0635\\u0648\\u064A\\u062A. \\u0628\\u062F\\u0647\\u0627 \\u062A\\u0635\\u0631\\u0641."
t["We good? Because that looked close."] = "\\u0646\\u062D\\u0646\\u0627 \\u062A\\u0645\\u0627\\u0645\\u061F \\u0644\\u0623\\u0646\\u0648 \\u0647\\u064A \\u0643\\u0627\\u0646\\u062A \\u0642\\u0631\\u064A\\u0628\\u0629."
t["We got a useful yield."] = "\\u0637\\u0644\\u0639 \\u0645\\u062D\\u0635\\u0648\\u0644 \\u0628\\u064A\\u0646\\u0641\\u0639."
t["We had each other's backs, %1. Mine belongs behind a locked door now."] = "\\u062D\\u0645\\u064A\\u0646\\u0627 \\u0636\\u0647\\u0631 \\u0628\\u0639\\u0636 \\u064A\\u0627 %1. \\u0636\\u0647\\u0631\\u064A \\u0647\\u0644\\u0623 \\u0645\\u0637\\u0631\\u062D\\u0647 \\u0648\\u0631\\u0627 \\u0628\\u0627\\u0628 \\u0645\\u0633\\u0643\\u0631."
t["We have a list of jobs longer than this table, %1."] = "\\u0639\\u0646\\u0627 \\u0642\\u0627\\u0626\\u0645\\u0629 \\u0634\\u063A\\u0644 \\u0623\\u0637\\u0648\\u0644 \\u0645\\u0646 \\u0647\\u0627\\u0644\\u0637\\u0627\\u0648\\u0644\\u0629 \\u064A\\u0627 %1."
t["We have a minute before moving on. What is on your mind, %1?"] = "\\u0645\\u0639\\u0646\\u0627 \\u062F\\u0642\\u064A\\u0642\\u0629 \\u0642\\u0628\\u0644 \\u0645\\u0627 \\u0646\\u0643\\u0645\\u0644. \\u0634\\u0648 \\u0628\\u0628\\u0627\\u0644\\u0643 \\u064A\\u0627 %1\\u061F"
t["We have a serious shortage of %1."] = "\\u0639\\u0646\\u0627 \\u0646\\u0642\\u0635 \\u0643\\u0628\\u064A\\u0631 \\u0628\\u0640 %1."
t["We have an arrangement. I'll let you know when it's more than that."] = "\\u0628\\u064A\\u0646\\u0627\\u062A\\u0646\\u0627 \\u0627\\u062A\\u0641\\u0627\\u0642. \\u0628\\u062E\\u0628\\u0631\\u0643 \\u0625\\u0630\\u0627 \\u0635\\u0627\\u0631 \\u0623\\u0643\\u062A\\u0631 \\u0645\\u0646 \\u0647\\u064A\\u0643."
t["We have become close. Closer than I expected anyone to get."] = "\\u0642\\u0631\\u0651\\u0628\\u0646\\u0627 \\u0645\\u0646 \\u0628\\u0639\\u0636. \\u0623\\u0643\\u062A\\u0631 \\u0645\\u0627 \\u0643\\u0646\\u062A \\u0645\\u062A\\u0648\\u0642\\u0639\\u0629 \\u062D\\u062F\\u0627 \\u064A\\u0642\\u0631\\u0651\\u0628."
t["We have been through enough that I know you will be there."] = "\\u0645\\u0631\\u0642\\u0646\\u0627 \\u0628\\u0643\\u062A\\u064A\\u0631 \\u0644\\u062F\\u0631\\u062C\\u0629 \\u0628\\u0639\\u0631\\u0641 \\u0625\\u0646\\u0643 \\u0631\\u062D \\u062A\\u0643\\u0648\\u0646 \\u0645\\u0648\\u062C\\u0648\\u062F."
