t["We have had worse days. We are still standing."] = "\\u0645\\u0631\\u0642 \\u0639\\u0644\\u064A\\u0646\\u0627 \\u0623\\u064A\\u0627\\u0645 \\u0623\\u0633\\u0648\\u0623. \\u0648\\u0644\\u0633\\u0627 \\u0648\\u0627\\u0642\\u0641\\u064A\\u0646."
