t["We have momentum. Let us use it without getting careless."] = "\\u0645\\u0627\\u0634\\u064A\\u064A\\u0646 \\u0645\\u0646\\u064A\\u062D. \\u062E\\u0644\\u064A\\u0646\\u0627 \\u0646\\u0633\\u062A\\u0641\\u064A\\u062F \\u0628\\u0644\\u0627 \\u0645\\u0627 \\u0646\\u0633\\u062A\\u0647\\u062A\\u0631."
t["We have more rules than the county council ever did."] = "\\u0639\\u0646\\u0627 \\u0642\\u0648\\u0627\\u0646\\u064A\\u0646 \\u0623\\u0643\\u062A\\u0631 \\u0645\\u0646 \\u0645\\u062C\\u0644\\u0633 \\u0627\\u0644\\u0645\\u0642\\u0627\\u0637\\u0639\\u0629."
t["We have survived worse together. Reach me!"] = "\\u0645\\u0631\\u0642\\u0646\\u0627 \\u0628\\u0623\\u0633\\u0648\\u0623 \\u0633\\u0648\\u0627. \\u0648\\u0635\\u0644 \\u0644\\u0639\\u0646\\u062F\\u064A!"
