t["We haven't had enough time for this to be goodbye!"] = "\\u0645\\u0627 \\u0643\\u0627\\u0646 \\u0639\\u0646\\u0627 \\u0648\\u0642\\u062A \\u0643\\u0641\\u0627\\u064A\\u0629 \\u0644\\u064A\\u0643\\u0648\\u0646 \\u0647\\u0627\\u062F \\u0648\\u062F\\u0627\\u0639!"
t["We keep avoiding the hard conversation."] = "\\u0644\\u0633\\u0627 \\u0639\\u0645 \\u0646\\u0647\\u0631\\u0628 \\u0645\\u0646 \\u0627\\u0644\\u062D\\u0643\\u064A \\u0627\\u0644\\u0635\\u0639\\u0628."
t["We keep gambling with our lives, and I am sick of it."] = "\\u0639\\u0645 \\u0646\\u0642\\u0627\\u0645\\u0631 \\u0628\\u062D\\u064A\\u0627\\u062A\\u0646\\u0627\\u060C \\u0648\\u0623\\u0646\\u0627 \\u0645\\u0644\\u064A\\u062A."
