t["We keep it quiet, and I keep an eye on you. Deal?"] = "\\u0645\\u0646\\u0633\\u0643\\u062A \\u0639\\u0646\\u0647\\u0627\\u060C \\u0648\\u0623\\u0646\\u0627 \\u0639\\u064A\\u0646\\u064A \\u0639\\u0644\\u064A\\u0643. \\u0627\\u062A\\u0641\\u0642\\u0646\\u0627\\u061F"
t["We keep saying %1 like there's still time for an answer."] = "\\u0644\\u0633\\u0627 \\u0645\\u0646\\u0642\\u0648\\u0644 %1 \\u0648\\u0643\\u0623\\u0646\\u0647 \\u0644\\u0633\\u0627 \\u0641\\u064A \\u0648\\u0642\\u062A \\u0644\\u062C\\u0648\\u0627\\u0628."
t["We keep stories because facts alone don't tell us how to live."] = "\\u0645\\u0646\\u062D\\u0641\\u0638 \\u0627\\u0644\\u0642\\u0635\\u0635 \\u0644\\u0623\\u0646\\u0648 \\u0627\\u0644\\u062D\\u0642\\u0627\\u064A\\u0642 \\u0644\\u062D\\u0627\\u0644\\u0647\\u0627 \\u0645\\u0627 \\u0628\\u062A\\u0639\\u0644\\u0645\\u0646\\u0627 \\u0643\\u064A\\u0641 \\u0646\\u0639\\u064A\\u0634."
t["We keep them close, keep watch, and treat them like a person."] = "\\u0645\\u0646\\u062E\\u0644\\u064A\\u0647\\u0646 \\u0642\\u0631\\u064A\\u0628\\u064A\\u0646\\u060C \\u0645\\u0646\\u0631\\u0627\\u0642\\u0628\\u060C \\u0648\\u0645\\u0646\\u0639\\u0627\\u0645\\u0644\\u0647\\u0646 \\u0645\\u062A\\u0644 \\u0627\\u0644\\u0628\\u0634\\u0631."
t["We kept each other alive longer than either of us expected."] = "\\u062E\\u0644\\u064A\\u0646\\u0627 \\u0628\\u0639\\u0636 \\u0639\\u0627\\u064A\\u0634\\u064A\\u0646 \\u0623\\u0643\\u062A\\u0631 \\u0645\\u0646 \\u0645\\u0627 \\u062A\\u0648\\u0642\\u0639\\u0646\\u0627."
t["We know your face. The house is still private."] = "\\u0645\\u0646\\u0639\\u0631\\u0641 \\u0648\\u062C\\u0647\\u0643. \\u0628\\u0633 \\u0627\\u0644\\u0628\\u064A\\u062A \\u0644\\u0633\\u0627 \\u062E\\u0627\\u0635."
t["We leave together. We come back together. That's the deal."] = "\\u0645\\u0646\\u0637\\u0644\\u0639 \\u0633\\u0648\\u0627 \\u0648\\u0645\\u0646\\u0631\\u062C\\u0639 \\u0633\\u0648\\u0627. \\u0647\\u0627\\u062F \\u0627\\u0644\\u0627\\u062A\\u0641\\u0627\\u0642."
t["We lost %1. I am not ready to pretend I am fine."] = "\\u062E\\u0633\\u0631\\u0646\\u0627 %1. \\u0645\\u0648 \\u062C\\u0627\\u0647\\u0632\\u0629 \\u0645\\u062B\\u0651\\u0644 \\u0625\\u0646\\u064A \\u0645\\u0646\\u064A\\u062D\\u0629."
t["We lost %1. We are keeping watch, but give us time to grieve."] = "\\u062E\\u0633\\u0631\\u0646\\u0627 %1. \\u0639\\u0645 \\u0646\\u062D\\u0631\\u0633\\u060C \\u0628\\u0633 \\u0627\\u0639\\u0637\\u064A\\u0646\\u0627 \\u0648\\u0642\\u062A \\u0646\\u062D\\u0632\\u0646."
t["We made a strong team. One of us can still make it home."] = "\\u0643\\u0646\\u0627 \\u0641\\u0631\\u064A\\u0642 \\u0642\\u0648\\u064A. \\u0648\\u0627\\u062D\\u062F \\u0645\\u0646\\u0627 \\u0644\\u0633\\u0627 \\u0641\\u064A\\u0647 \\u064A\\u0648\\u0635\\u0644 \\u0639\\u0627\\u0644\\u0628\\u064A\\u062A."
t["We made it back. I will take that victory, %1."] = "\\u0631\\u062C\\u0639\\u0646\\u0627. \\u0648\\u0647\\u0627\\u062F \\u0646\\u0635\\u0631 \\u0628\\u0642\\u0628\\u0644\\u0647 \\u064A\\u0627 %1."
t["We made it this far together. That has to count for something."] = "\\u0648\\u0635\\u0644\\u0646\\u0627 \\u0644\\u0647\\u0648\\u0646 \\u0633\\u0648\\u0627. \\u0647\\u0627\\u062F \\u0644\\u0627\\u0632\\u0645 \\u064A\\u0639\\u0646\\u064A \\u0634\\u064A."
t["We made it. Look for supplies and call out what you find."] = "\\u0648\\u0635\\u0644\\u0646\\u0627. \\u062F\\u0648\\u0631\\u0648\\u0627 \\u0639\\u0627\\u0644\\u0645\\u0648\\u0646\\u0629 \\u0648\\u0646\\u0627\\u062F\\u0648\\u0627 \\u0639\\u0627\\u0644\\u0644\\u064A \\u0628\\u062A\\u0644\\u0627\\u0642\\u0648\\u0647."
t["We made the best call we had. Shouting will not change it."] = "\\u0623\\u062E\\u062F\\u0646\\u0627 \\u0623\\u062D\\u0633\\u0646 \\u0642\\u0631\\u0627\\u0631 \\u0643\\u0627\\u0646 \\u0639\\u0646\\u0627. \\u0627\\u0644\\u0635\\u0631\\u064A\\u062E \\u0645\\u0627 \\u0628\\u063A\\u064A\\u0631\\u0647."
t["We need %1. More than we need another promise."] = "\\u0628\\u062F\\u0646\\u0627 %1. \\u0623\\u0643\\u062A\\u0631 \\u0645\\u0627 \\u0628\\u062F\\u0646\\u0627 \\u0648\\u0639\\u062F \\u062C\\u062F\\u064A\\u062F."
t["We need %1. Pride isn't worth anybody suffering for."] = "\\u0628\\u062F\\u0646\\u0627 %1. \\u0627\\u0644\\u0643\\u0631\\u0627\\u0645\\u0629 \\u0645\\u0627 \\u0628\\u062A\\u0633\\u062A\\u0627\\u0647\\u0644 \\u0625\\u0646\\u0648 \\u062D\\u062F\\u0627 \\u064A\\u062A\\u0639\\u0630\\u0628."
t["We need %1. Tell us whether you can help."] = "\\u0628\\u062F\\u0646\\u0627 %1. \\u0642\\u0644\\u0646\\u0627 \\u0625\\u0630\\u0627 \\u0641\\u064A\\u0643 \\u062A\\u0633\\u0627\\u0639\\u062F."
t["We need a proper chopping tool before I go back out there."] = "\\u0628\\u062F\\u0646\\u0627 \\u0634\\u064A \\u0645\\u0646\\u064A\\u062D \\u0644\\u0644\\u0642\\u0637\\u0639 \\u0642\\u0628\\u0644 \\u0645\\u0627 \\u0627\\u0631\\u062C\\u0639 \\u0644\\u0628\\u0631\\u0651\\u0627."
t["We need a secure room and someone on watch."] = "\\u0628\\u062F\\u0646\\u0627 \\u063A\\u0631\\u0641\\u0629 \\u0645\\u0623\\u0645\\u0646\\u0629 \\u0648\\u062D\\u062F\\u0627 \\u0639\\u0627\\u0644\\u062D\\u0631\\u0627\\u0633\\u0629."
t["We need a shelter that gives us time to react when trouble comes."] = "\\u0628\\u062F\\u0646\\u0627 \\u0645\\u0644\\u062C\\u0623 \\u064A\\u0639\\u0637\\u064A\\u0646\\u0627 \\u0648\\u0642\\u062A \\u0646\\u062A\\u0635\\u0631\\u0641 \\u0644\\u0645\\u0627 \\u062A\\u062C\\u064A \\u0627\\u0644\\u0645\\u0635\\u064A\\u0628\\u0629."
t["We need a working hammer from a shed or garage."] = "\\u0628\\u062F\\u0646\\u0627 \\u0634\\u0627\\u0643\\u0648\\u0634 \\u0634\\u063A\\u0651\\u0627\\u0644 \\u0645\\u0646 \\u0634\\u064A \\u0645\\u062E\\u0632\\u0646 \\u0623\\u0648 \\u0643\\u0631\\u0627\\u062C."
t["We need bait before I cast again."] = "\\u0628\\u062F\\u0646\\u0627 \\u0637\\u0639\\u0645 \\u0642\\u0628\\u0644 \\u0645\\u0627 \\u0627\\u0631\\u0645\\u064A \\u0645\\u0631\\u0629 \\u062A\\u0627\\u0646\\u064A\\u0629."
t["We need more clean bandages in reserve."] = "\\u0628\\u062F\\u0646\\u0627 \\u0634\\u0627\\u0634 \\u0646\\u0636\\u064A\\u0641 \\u0632\\u064A\\u0627\\u062F\\u0629 \\u0627\\u062D\\u062A\\u064A\\u0627\\u0637."
t["We need somewhere safe enough to sleep."] = "\\u0644\\u0627\\u0632\\u0645 \\u0646\\u0644\\u0627\\u0642\\u064A \\u0645\\u062D\\u0644 \\u0622\\u0645\\u0646 \\u0643\\u0641\\u0627\\u064A\\u0629 \\u0644\\u0646\\u0646\\u0627\\u0645."
t["We need space. Now. I cannot think in this crowd."] = "\\u0628\\u062F\\u0646\\u0627 \\u0645\\u062C\\u0627\\u0644. \\u0647\\u0644\\u0623. \\u0645\\u0627 \\u0641\\u064A\\u0646\\u064A \\u0641\\u0643\\u0631 \\u0628\\u0647\\u0627\\u0644\\u0632\\u062D\\u0645\\u0629."
t["We need to find clean water."] = "\\u0644\\u0627\\u0632\\u0645 \\u0646\\u0644\\u0627\\u0642\\u064A \\u0645\\u064A \\u0646\\u0636\\u064A\\u0641\\u0629."
t["We need to find something I can eat."] = "\\u0644\\u0627\\u0632\\u0645 \\u0646\\u0644\\u0627\\u0642\\u064A \\u0634\\u064A \\u0622\\u0643\\u0644\\u0647."
t["We need to know why this failed before we repeat it."] = "\\u0644\\u0627\\u0632\\u0645 \\u0646\\u0639\\u0631\\u0641 \\u0644\\u064A\\u0634 \\u0641\\u0634\\u0644 \\u0642\\u0628\\u0644 \\u0645\\u0627 \\u0646\\u0639\\u064A\\u062F\\u0647\\u0627."
t["We need to stop making the same mistakes."] = "\\u0644\\u0627\\u0632\\u0645 \\u0646\\u0648\\u0642\\u0641 \\u0646\\u0639\\u064A\\u062F \\u0646\\u0641\\u0633 \\u0627\\u0644\\u063A\\u0644\\u0637\\u0627\\u062A."
t["We need to talk about the last run. You took a risk with all of us."] = "\\u0644\\u0627\\u0632\\u0645 \\u0646\\u062D\\u0643\\u064A \\u0639\\u0646 \\u0622\\u062E\\u0631 \\u0645\\u0634\\u0648\\u0627\\u0631. \\u062E\\u0627\\u0637\\u0631\\u062A \\u0641\\u064A\\u0646\\u0627 \\u0643\\u0644\\u0646\\u0627."
t["We need to talk before that risk becomes a pattern."] = "\\u0644\\u0627\\u0632\\u0645 \\u0646\\u062D\\u0643\\u064A \\u0642\\u0628\\u0644 \\u0645\\u0627 \\u062A\\u0635\\u064A\\u0631 \\u0647\\u0627\\u0644\\u0645\\u062E\\u0627\\u0637\\u0631\\u0629 \\u0639\\u0627\\u062F\\u0629."
t["We need to talk somewhere private. I may be infected."] = "\\u0644\\u0627\\u0632\\u0645 \\u0646\\u062D\\u0643\\u064A \\u0628\\u0645\\u062D\\u0644 \\u0644\\u062D\\u0627\\u0644\\u0646\\u0627. \\u064A\\u0645\\u0643\\u0646 \\u0623\\u0646\\u0627 \\u0645\\u0644\\u0642\\u0648\\u0637\\u0629."
t["We owe the dead more than remembering how they died."] = "\\u0627\\u0644\\u0645\\u064A\\u062A\\u064A\\u0646 \\u0625\\u0644\\u0647\\u0645 \\u0639\\u0644\\u064A\\u0646\\u0627 \\u0623\\u0643\\u062A\\u0631 \\u0645\\u0646 \\u0625\\u0646\\u0648 \\u0646\\u062A\\u0630\\u0643\\u0631 \\u0643\\u064A\\u0641 \\u0645\\u0627\\u062A\\u0648\\u0627."
t["We remember you. Say what you came to say."] = "\\u0645\\u062A\\u0630\\u0643\\u0631\\u064A\\u0646\\u0643. \\u0642\\u0648\\u0644 \\u0627\\u0644\\u0644\\u064A \\u0627\\u062C\\u064A\\u062A \\u062A\\u0642\\u0648\\u0644\\u0647."
t["We see you. Do not approach the house."] = "\\u0634\\u0627\\u064A\\u0641\\u064A\\u0646\\u0643. \\u0644\\u0627 \\u062A\\u0642\\u0631\\u0628 \\u0639\\u0627\\u0644\\u0628\\u064A\\u062A."
t["We should count what we carry before moving on."] = "\\u0644\\u0627\\u0632\\u0645 \\u0646\\u0639\\u062F\\u0651 \\u0627\\u0644\\u0644\\u064A \\u0645\\u0639\\u0646\\u0627 \\u0642\\u0628\\u0644 \\u0645\\u0627 \\u0646\\u0643\\u0645\\u0644."
t["We should decide which chore gets daylight first."] = "\\u0644\\u0627\\u0632\\u0645 \\u0646\\u0642\\u0631\\u0631 \\u0623\\u064A \\u0634\\u063A\\u0644\\u0629 \\u062A\\u0627\\u062E\\u062F \\u0627\\u0644\\u0646\\u0647\\u0627\\u0631 \\u0623\\u0648\\u0644."
t["We should eat together more often, even when the menu's grim."] = "\\u0644\\u0627\\u0632\\u0645 \\u0646\\u0627\\u0643\\u0644 \\u0633\\u0648\\u0627 \\u0623\\u0643\\u062A\\u0631\\u060C \\u062D\\u062A\\u0649 \\u0644\\u0648 \\u0627\\u0644\\u0623\\u0643\\u0644 \\u0628\\u064A\\u0628\\u0643\\u0651\\u064A."
t["We should find clean bandages before someone needs one."] = "\\u0644\\u0627\\u0632\\u0645 \\u0646\\u0644\\u0627\\u0642\\u064A \\u0634\\u0627\\u0634 \\u0646\\u0636\\u064A\\u0641 \\u0642\\u0628\\u0644 \\u0645\\u0627 \\u062D\\u062F\\u0627 \\u064A\\u062D\\u062A\\u0627\\u062C\\u0647."
t["We should have enough medical supplies that a cut doesn't become a crisis."] = "\\u0644\\u0627\\u0632\\u0645 \\u064A\\u0643\\u0648\\u0646 \\u0639\\u0646\\u0627 \\u0645\\u0648\\u0627\\u062F \\u0637\\u0628\\u064A\\u0629 \\u062A\\u0643\\u0641\\u064A\\u060C \\u0644\\u062D\\u062A\\u0649 \\u0627\\u0644\\u062C\\u0631\\u062D \\u0645\\u0627 \\u064A\\u0635\\u064A\\u0631 \\u0643\\u0627\\u0631\\u062B\\u0629."
t["We should hold on to the little things. They add up."] = "\\u0644\\u0627\\u0632\\u0645 \\u0646\\u062A\\u0645\\u0633\\u0643 \\u0628\\u0627\\u0644\\u0634\\u063A\\u0644\\u0627\\u062A \\u0627\\u0644\\u0635\\u063A\\u064A\\u0631\\u0629. \\u0628\\u062A\\u062A\\u062C\\u0645\\u0639."
t["We should keep an eye out for clean water."] = "\\u0644\\u0627\\u0632\\u0645 \\u0646\\u0636\\u0644 \\u0645\\u0641\\u062A\\u062D\\u064A\\u0646 \\u0639\\u0644\\u0649 \\u0645\\u064A \\u0646\\u0636\\u064A\\u0641\\u0629."
t["We should look for a fishing rod on the next supply run."] = "\\u0644\\u0627\\u0632\\u0645 \\u0646\\u062F\\u0648\\u0631 \\u0639\\u0644\\u0649 \\u0635\\u0646\\u0627\\u0631\\u0629 \\u0628\\u0645\\u0634\\u0648\\u0627\\u0631\\u0646\\u0627 \\u0627\\u0644\\u062C\\u0627\\u064A."
t["We should look through the kitchen drawers for a decent knife."] = "\\u0644\\u0627\\u0632\\u0645 \\u0646\\u0641\\u062A\\u0634 \\u062C\\u0648\\u0627\\u0631\\u064A\\u0631 \\u0627\\u0644\\u0645\\u0637\\u0628\\u062E \\u0639\\u0644\\u0649 \\u0633\\u0643\\u064A\\u0646\\u0629 \\u0645\\u0646\\u064A\\u062D\\u0629."
t["We should put the equipment in order while it is still fixable."] = "\\u0644\\u0627\\u0632\\u0645 \\u0646\\u0631\\u062A\\u0628 \\u0627\\u0644\\u0639\\u062F\\u0629 \\u0637\\u0627\\u0644\\u0645\\u0627 \\u0644\\u0633\\u0627 \\u0628\\u062A\\u062A\\u0635\\u0644\\u062D."
t["We should review tomorrow's plan."] = "\\u0644\\u0627\\u0632\\u0645 \\u0646\\u0631\\u0627\\u062C\\u0639 \\u062E\\u0637\\u0629 \\u0628\\u0643\\u0631\\u0627."
t["We should search a toolbox for a working screwdriver."] = "\\u0644\\u0627\\u0632\\u0645 \\u0646\\u0641\\u062A\\u0634 \\u0635\\u0646\\u062F\\u0648\\u0642 \\u0639\\u062F\\u0629 \\u0639\\u0644\\u0649 \\u0645\\u0641\\u0643 \\u0634\\u063A\\u0651\\u0627\\u0644."
t["We should search a workshop for a saw before trying this again."] = "\\u0644\\u0627\\u0632\\u0645 \\u0646\\u0641\\u062A\\u0634 \\u0634\\u064A \\u0648\\u0631\\u0634\\u0629 \\u0639\\u0644\\u0649 \\u0645\\u0646\\u0634\\u0627\\u0631 \\u0642\\u0628\\u0644 \\u0645\\u0627 \\u0646\\u062C\\u0631\\u0628 \\u0645\\u0631\\u0629 \\u062A\\u0627\\u0646\\u064A\\u0629."
t["We should show the others this part."] = "\\u0644\\u0627\\u0632\\u0645 \\u0646\\u0641\\u0631\\u062C\\u064A \\u0627\\u0644\\u0628\\u0627\\u0642\\u064A\\u064A\\u0646 \\u0647\\u0627\\u0644\\u0642\\u0633\\u0645."
t["We should stop and eat before I make a bad mistake."] = "\\u0644\\u0627\\u0632\\u0645 \\u0646\\u0648\\u0642\\u0641 \\u0648\\u0646\\u0627\\u0643\\u0644 \\u0642\\u0628\\u0644 \\u0645\\u0627 \\u0627\\u0639\\u0645\\u0644 \\u063A\\u0644\\u0637\\u0629 \\u0639\\u0627\\u0637\\u0644\\u0629."
t["We should talk about our next run. When are we going?"] = "\\u0644\\u0627\\u0632\\u0645 \\u0646\\u062D\\u0643\\u064A \\u0628\\u0627\\u0644\\u0645\\u0634\\u0648\\u0627\\u0631 \\u0627\\u0644\\u062C\\u0627\\u064A. \\u0625\\u064A\\u0645\\u062A \\u0631\\u0627\\u064A\\u062D\\u064A\\u0646\\u061F"
t["We should write our names somewhere. For whoever finds us."] = "\\u0644\\u0627\\u0632\\u0645 \\u0646\\u0643\\u062A\\u0628 \\u0623\\u0633\\u0627\\u0645\\u064A\\u0646\\u0627 \\u0628\\u0645\\u062D\\u0644. \\u0644\\u0645\\u064A\\u0646 \\u0645\\u0627 \\u0644\\u0642\\u0627\\u0646\\u0627."
t["We stay together and avoid fights that put either of us at needless risk."] = "\\u0645\\u0646\\u0636\\u0644 \\u0633\\u0648\\u0627 \\u0648\\u0645\\u0646\\u0628\\u0639\\u062F \\u0639\\u0646 \\u0642\\u062A\\u0627\\u0644 \\u0628\\u064A\\u062E\\u0627\\u0637\\u0631 \\u0628\\u062D\\u062F\\u0627 \\u0645\\u0646\\u0627 \\u0639\\u0627\\u0644\\u0641\\u0627\\u0636\\u064A."
t["We stay with them. Whatever comes, they won't face it alone."] = "\\u0645\\u0646\\u0636\\u0644 \\u0645\\u0639\\u0647\\u0646. \\u0634\\u0648 \\u0645\\u0627 \\u0635\\u0627\\u0631\\u060C \\u0645\\u0648 \\u0631\\u062D \\u064A\\u0648\\u0627\\u062C\\u0647\\u0648\\u0647 \\u0644\\u062D\\u0627\\u0644\\u0647\\u0646."
t["We still have work to do. I just need a moment for %1 first."] = "\\u0644\\u0633\\u0627 \\u0639\\u0646\\u0627 \\u0634\\u063A\\u0644. \\u0628\\u0633 \\u0628\\u062F\\u064A \\u0644\\u062D\\u0638\\u0629 \\u0644\\u0640%1 \\u0623\\u0648\\u0644."
t["We still know how to do something besides lose things."] = "\\u0644\\u0633\\u0627 \\u0645\\u0646\\u0639\\u0631\\u0641 \\u0646\\u0639\\u0645\\u0644 \\u0634\\u064A \\u063A\\u064A\\u0631 \\u0625\\u0646\\u0647 \\u0646\\u062E\\u0633\\u0631."
t["We survived too much for it to end here!"] = "\\u0639\\u0634\\u0646\\u0627 \\u0643\\u062A\\u064A\\u0631 \\u0644\\u062A\\u062E\\u0644\\u0635 \\u0647\\u0648\\u0646!"
t["We survived, but that does not make the choices we made good ones."] = "\\u0637\\u0644\\u0639\\u0646\\u0627 \\u0639\\u0627\\u064A\\u0634\\u064A\\u0646\\u060C \\u0628\\u0633 \\u0647\\u0627\\u062F \\u0645\\u0627 \\u0628\\u064A\\u062E\\u0644\\u064A \\u0642\\u0631\\u0627\\u0631\\u0627\\u062A\\u0646\\u0627 \\u0645\\u0646\\u064A\\u062D\\u0629."
t["We trust you. We still keep the house secure."] = "\\u0645\\u0646\\u0648\\u062B\\u0642 \\u0641\\u064A\\u0643. \\u0648\\u0628\\u0631\\u0636\\u0648 \\u0645\\u0646\\u0636\\u0644 \\u0646\\u0623\\u0645\\u0651\\u0646 \\u0627\\u0644\\u0628\\u064A\\u062A."
t["We walk much farther, I'm calling it a pilgrimage."] = "\\u0625\\u0630\\u0627 \\u0645\\u0634\\u064A\\u0646\\u0627 \\u0623\\u0643\\u062A\\u0631\\u060C \\u0631\\u062D \\u0633\\u0645\\u0651\\u064A\\u0647\\u0627 \\u062D\\u062C."
t["We watch the fever, keep a door between us at night, and decide from facts."] = "\\u0645\\u0646\\u0631\\u0627\\u0642\\u0628 \\u0627\\u0644\\u062D\\u0631\\u0627\\u0631\\u0629\\u060C \\u0645\\u0646\\u062E\\u0644\\u064A \\u0628\\u0627\\u0628 \\u0628\\u064A\\u0646\\u0627\\u062A\\u0646\\u0627 \\u0628\\u0627\\u0644\\u0644\\u064A\\u0644\\u060C \\u0648\\u0645\\u0646\\u0642\\u0631\\u0631 \\u0639\\u0627\\u0644\\u0648\\u0642\\u0627\\u064A\\u0639."
t["We were a good team, weren't we?"] = "\\u0643\\u0646\\u0627 \\u0641\\u0631\\u064A\\u0642 \\u0645\\u0646\\u064A\\u062D, \\u0645\\u0648 \\u0647\\u064A\\u0643?"
t["We will be honest:"] = "\\u0631\\u062D \\u0646\\u0643\\u0648\\u0646 \\u0635\\u0631\\u064A\\u062D\\u064A\\u0646:"
t["We will tell you this much:"] = "\\u0631\\u062D \\u0646\\u0642\\u0644\\u0643 \\u0644\\u0647\\u0648\\u0646 \\u0648\\u0628\\u0633:"
t["We won the moment. Now let me keep everyone standing."] = "\\u0631\\u0628\\u062D\\u0646\\u0627 \\u0627\\u0644\\u0644\\u062D\\u0638\\u0629. \\u0647\\u0644\\u0623 \\u062E\\u0644\\u064A\\u0646\\u064A \\u0636\\u0644\\u0643\\u0646 \\u0648\\u0627\\u0642\\u0641\\u064A\\u0646."
t["We won't cut through that metal without a working torch."] = "\\u0645\\u0627 \\u0631\\u062D \\u0646\\u0642\\u0635 \\u0647\\u0627\\u0644\\u062D\\u062F\\u064A\\u062F \\u0628\\u0644\\u0627 \\u0634\\u0627\\u0644\\u064A\\u0645\\u0648 \\u0634\\u063A\\u0651\\u0627\\u0644."
t["We won't turn logs into planks without a saw."] = "\\u0645\\u0627 \\u0631\\u062D \\u062A\\u0635\\u064A\\u0631 \\u0627\\u0644\\u062C\\u0630\\u0648\\u0639 \\u0623\\u0644\\u0648\\u0627\\u062D \\u0628\\u0644\\u0627 \\u0645\\u0646\\u0634\\u0627\\u0631."
t["We work well together. Trust takes time, but we are getting there."] = "\\u0645\\u0646\\u0634\\u062A\\u063A\\u0644 \\u0645\\u0646\\u064A\\u062D \\u0645\\u0639 \\u0628\\u0639\\u0636. \\u0627\\u0644\\u062B\\u0642\\u0629 \\u0628\\u062F\\u0647\\u0627 \\u0648\\u0642\\u062A\\u060C \\u0628\\u0633 \\u0639\\u0645 \\u0646\\u0648\\u0635\\u0644."
t["We'd make a very well-organised ghost town."] = "\\u0643\\u0646\\u0627 \\u0631\\u062D \\u0646\\u0639\\u0645\\u0644 \\u0628\\u0644\\u062F\\u0629 \\u0623\\u0634\\u0628\\u0627\\u062D \\u0643\\u062A\\u064A\\u0631 \\u0645\\u0646\\u0638\\u0645\\u0629."
t["We'll clean the old cloth when we find water."] = "\\u0645\\u0646\\u063A\\u0633\\u0644 \\u0627\\u0644\\u0642\\u0645\\u0627\\u0634 \\u0627\\u0644\\u0642\\u062F\\u064A\\u0645 \\u0644\\u0645\\u0627 \\u0646\\u0644\\u0627\\u0642\\u064A \\u0645\\u064A."
t["We'll get it straight, then keep it still."] = "\\u0645\\u0646\\u0639\\u062F\\u0651\\u0644\\u0647\\u0627\\u060C \\u0648\\u0628\\u0639\\u062F\\u064A\\u0646 \\u0645\\u0646\\u062B\\u0628\\u062A\\u0647\\u0627."
t["We'll have to search the sheds for a shovel."] = "\\u0644\\u0627\\u0632\\u0645 \\u0646\\u0641\\u062A\\u0634 \\u0627\\u0644\\u0645\\u062E\\u0627\\u0632\\u0646 \\u0639\\u0644\\u0649 \\u0643\\u0631\\u064A\\u0643."
t["We'll keep the Kentucky dust out of this one."] = "\\u0645\\u0646\\u062E\\u0644\\u064A \\u063A\\u0628\\u0631\\u0629 \\u0643\\u0646\\u062A\\u0627\\u0643\\u064A \\u0628\\u0631\\u0651\\u0627\\u062A \\u0647\\u0627\\u062F \\u0627\\u0644\\u062C\\u0631\\u062D."
t["We'll leave a note by the door so nobody misses it."] = "\\u0645\\u0646\\u062A\\u0631\\u0643 \\u0648\\u0631\\u0642\\u0629 \\u062C\\u0646\\u0628 \\u0627\\u0644\\u0628\\u0627\\u0628 \\u0644\\u062D\\u062A\\u0649 \\u0645\\u0627 \\u062A\\u0641\\u0648\\u062A \\u062D\\u062F\\u0627."
t["We'll listen from this side of the glass, then."] = "\\u0637\\u064A\\u0628 \\u0645\\u0646\\u0633\\u0645\\u0639 \\u0645\\u0646 \\u0647\\u0627\\u0644\\u062C\\u0647\\u0629 \\u0645\\u0646 \\u0627\\u0644\\u0642\\u0632\\u0627\\u0632."
t["We'll put another log on before the cold gets ideas."] = "\\u0645\\u0646\\u062D\\u0637 \\u062D\\u0637\\u0628\\u0629 \\u0643\\u0645\\u0627\\u0646 \\u0642\\u0628\\u0644 \\u0645\\u0627 \\u064A\\u062A\\u0634\\u0627\\u0637\\u0631 \\u0627\\u0644\\u0628\\u0631\\u062F."
t["We'll take what we need and leave the ghosts their furniture."] = "\\u0645\\u0646\\u0627\\u062E\\u062F \\u0627\\u0644\\u0644\\u064A \\u0628\\u062F\\u0646\\u0627 \\u064A\\u0627\\u0647 \\u0648\\u0645\\u0646\\u062A\\u0631\\u0643 \\u0644\\u0644\\u0623\\u0634\\u0628\\u0627\\u062D \\u0639\\u0641\\u0634\\u0647\\u0645."
t["We're a metal box full of snacks, as far as they're concerned."] = "\\u0628\\u0627\\u0644\\u0646\\u0633\\u0628\\u0629 \\u0625\\u0644\\u0647\\u0645 \\u0646\\u062D\\u0646\\u0627 \\u0639\\u0644\\u0628\\u0629 \\u062D\\u062F\\u064A\\u062F \\u0645\\u0644\\u064A\\u0627\\u0646\\u0629 \\u0633\\u0646\\u0627\\u0643\\u0627\\u062A."
t["We're all just very slow corpses with better manners."] = "\\u0643\\u0644\\u0646\\u0627 \\u062C\\u062B\\u062B \\u0628\\u0637\\u064A\\u0626\\u0629 \\u0643\\u062A\\u064A\\u0631 \\u0628\\u0633 \\u0623\\u062E\\u0644\\u0627\\u0642\\u0646\\u0627 \\u0623\\u062D\\u0633\\u0646."
t["We're all thinking it. You just say it."] = "\\u0643\\u0644\\u0646\\u0627 \\u0639\\u0645 \\u0646\\u0641\\u0643\\u0631 \\u0641\\u064A\\u0647\\u0627. \\u0628\\u0633 \\u0625\\u0646\\u062A \\u0628\\u062A\\u0642\\u0648\\u0644\\u0647\\u0627."
t["We're back, all of us. Now let me look at you for a change."] = "\\u0631\\u062C\\u0639\\u0646\\u0627\\u060C \\u0643\\u0644\\u0646\\u0627. \\u0647\\u0644\\u0623 \\u062E\\u0644\\u064A\\u0646\\u064A \\u0627\\u062A\\u0637\\u0644\\u0639 \\u0641\\u064A\\u0643 \\u0644\\u0645\\u0631\\u0629."
t["We're back. Everybody who left is standing right here."] = "\\u0631\\u062C\\u0639\\u0646\\u0627. \\u0643\\u0644 \\u0627\\u0644\\u0644\\u064A \\u0637\\u0644\\u0639\\u0648\\u0627 \\u0648\\u0627\\u0642\\u0641\\u064A\\u0646 \\u0647\\u0648\\u0646."
t["We're back. Give us a minute, then you get the full report."] = "\\u0631\\u062C\\u0639\\u0646\\u0627. \\u0639\\u0637\\u0648\\u0646\\u0627 \\u062F\\u0642\\u064A\\u0642\\u0629\\u060C \\u0648\\u0628\\u0639\\u062F\\u064A\\u0646 \\u0628\\u062A\\u0627\\u062E\\u062F\\u0648\\u0627 \\u0627\\u0644\\u062A\\u0642\\u0631\\u064A\\u0631 \\u0643\\u0627\\u0645\\u0644."
t["We're back. I checked behind us twice. Keep an eye on the road anyway."] = "\\u0631\\u062C\\u0639\\u0646\\u0627. \\u0634\\u064A\\u0643\\u062A \\u0648\\u0631\\u0627\\u0646\\u0627 \\u0645\\u0631\\u062A\\u064A\\u0646. \\u0636\\u0644 \\u0639\\u064A\\u0646\\u0643 \\u0639\\u0627\\u0644\\u0637\\u0631\\u064A\\u0642 \\u0628\\u0631\\u0636\\u0648."
t["We're being compressed! Get out!"] = "\\u0639\\u0645 \\u064A\\u0639\\u0635\\u0631\\u0648\\u0646\\u0627! \\u0627\\u0637\\u0644\\u0639!"
t["We're being overrun!"] = "\\u0639\\u0645 \\u064A\\u0643\\u062A\\u0633\\u062D\\u0648\\u0646\\u0627!"
t["We're closed! Go home!"] = "\\u0645\\u0633\\u0643\\u0631\\u064A\\u0646! \\u0631\\u0648\\u062D \\u0639\\u0627\\u0644\\u0628\\u064A\\u062A!"
t["We're done. Don't follow me."] = "\\u062E\\u0644\\u0635\\u0646\\u0627. \\u0644\\u0627 \\u062A\\u0644\\u062D\\u0642\\u0646\\u064A."
t["We're keeping a museum nobody visits."] = "\\u0646\\u062D\\u0646\\u0627 \\u0639\\u0645 \\u0646\\u062D\\u0631\\u0633 \\u0645\\u062A\\u062D\\u0641 \\u0645\\u0627 \\u062D\\u062F\\u0627 \\u0628\\u064A\\u0632\\u0648\\u0631\\u0647."
t["We're losing daylight. I want walls around us soon."] = "\\u0639\\u0645 \\u0646\\u062E\\u0633\\u0631 \\u0627\\u0644\\u0636\\u0648. \\u0628\\u062F\\u064A \\u062D\\u064A\\u0637\\u0627\\u0646 \\u062D\\u0648\\u0644\\u064A\\u0646\\u0627 \\u0642\\u0631\\u064A\\u0628\\u0627\\u064B."
t["We're losing space. Withdraw!"] = "\\u0639\\u0645 \\u0646\\u062E\\u0633\\u0631 \\u0627\\u0644\\u0645\\u0637\\u0631\\u062D. \\u0627\\u0646\\u0633\\u062D\\u0628!"
t["We're not family. But you're not just another mouth to feed."] = "\\u0645\\u0648 \\u0623\\u0647\\u0644. \\u0628\\u0633 \\u0643\\u0645\\u0627\\u0646 \\u0625\\u0646\\u062A \\u0645\\u0648 \\u0645\\u062C\\u0631\\u062F \\u062A\\u0645 \\u0632\\u064A\\u0627\\u062F\\u0629 \\u0644\\u0627\\u0632\\u0645 \\u064A\\u0646\\u0637\\u0639\\u0645."
t["We're not holding here! Clear the exit!"] = "\\u0645\\u0648 \\u0631\\u062D \\u0646\\u0635\\u0645\\u062F \\u0647\\u0648\\u0646! \\u0646\\u0636\\u0641 \\u0627\\u0644\\u0645\\u062E\\u0631\\u062C!"
t["We're not surviving. We're just dying slower than everybody else."] = "\\u0646\\u062D\\u0646\\u0627 \\u0645\\u0648 \\u0639\\u0627\\u064A\\u0634\\u064A\\u0646. \\u0628\\u0633 \\u0639\\u0645 \\u0646\\u0645\\u0648\\u062A \\u0623\\u0628\\u0637\\u0623 \\u0645\\u0646 \\u063A\\u064A\\u0631\\u0646\\u0627."
t["We're not surviving. We're just dying slower than the other bastards."] = "\\u0646\\u062D\\u0646\\u0627 \\u0645\\u0648 \\u0639\\u0627\\u064A\\u0634\\u064A\\u0646. \\u0628\\u0633 \\u0639\\u0645 \\u0646\\u0645\\u0648\\u062A \\u0623\\u0628\\u0637\\u0623 \\u0645\\u0646 \\u0648\\u0644\\u0627\\u062F \\u0627\\u0644\\u0643\\u0644\\u0628 \\u0627\\u0644\\u062A\\u0627\\u0646\\u064A\\u064A\\u0646."
t["We're out of the nails this needs."] = "\\u062E\\u0644\\u0635\\u0648\\u0627 \\u0627\\u0644\\u0628\\u0633\\u0627\\u0645\\u064A\\u0631 \\u0627\\u0644\\u0644\\u064A \\u0628\\u062F\\u0646\\u0627 \\u064A\\u0627\\u0647\\u0646."
t["We're short on %1. I'd rather say it before it gets worse."] = "\\u0646\\u0627\\u0642\\u0635\\u0646\\u0627 %1. \\u0628\\u0641\\u0636\\u0651\\u0644 \\u0642\\u0648\\u0644\\u0647\\u0627 \\u0642\\u0628\\u0644 \\u0645\\u0627 \\u062A\\u0633\\u0648\\u0621."
t["We're short on %1. That's the part we can't talk around."] = "\\u0646\\u0627\\u0642\\u0635\\u0646\\u0627 %1. \\u0648\\u0647\\u064A \\u0627\\u0644\\u0634\\u063A\\u0644\\u0629 \\u0627\\u0644\\u0644\\u064A \\u0645\\u0627 \\u0641\\u064A\\u0646\\u0627 \\u0646\\u0644\\u0641 \\u062D\\u0648\\u0627\\u0644\\u064A\\u0647\\u0627."
t["We're short on bowls. Check the kitchen cupboards."] = "\\u0646\\u0627\\u0642\\u0635\\u0646\\u0627 \\u0632\\u0628\\u0627\\u062F\\u064A. \\u0634\\u0648\\u0641 \\u0628\\u062E\\u0632\\u0627\\u064A\\u0646 \\u0627\\u0644\\u0645\\u0637\\u0628\\u062E."
t["We're short one plank for this."] = "\\u0646\\u0627\\u0642\\u0635\\u0646\\u0627 \\u0644\\u0648\\u062D \\u062E\\u0634\\u0628 \\u0644\\u0647\\u064A \\u0627\\u0644\\u0634\\u063A\\u0644\\u0629."
t["We're still parked. At least the scenery is dependable."] = "\\u0644\\u0633\\u0627 \\u0635\\u0627\\u0641\\u0651\\u064A\\u0646. \\u0639\\u0627\\u0644\\u0623\\u0642\\u0644 \\u0627\\u0644\\u0645\\u0646\\u0638\\u0631 \\u062B\\u0627\\u0628\\u062A."
t["We're the neighbours now. Somebody's bad neighbours."] = "\\u0646\\u062D\\u0646\\u0627 \\u0627\\u0644\\u062C\\u064A\\u0631\\u0627\\u0646 \\u0647\\u0644\\u0623. \\u062C\\u064A\\u0631\\u0627\\u0646 \\u0639\\u0627\\u0637\\u0644\\u064A\\u0646 \\u0644\\u062D\\u062F\\u0627."
t["We're too close to them. Come back with me."] = "\\u0646\\u062D\\u0646\\u0627 \\u0642\\u0631\\u0627\\u0628 \\u0643\\u062A\\u064A\\u0631 \\u0645\\u0646\\u0647\\u0646. \\u0627\\u0631\\u062C\\u0639 \\u0645\\u0639\\u064A."
t["We've announced ourselves. I'd rather relocate than meet the audience."] = "\\u0623\\u0639\\u0644\\u0646\\u0651\\u0627 \\u0639\\u0646 \\u062D\\u0627\\u0644\\u0646\\u0627. \\u0628\\u0641\\u0636\\u0651\\u0644 \\u0646\\u0646\\u0642\\u0644 \\u0645\\u0637\\u0631\\u062D\\u0646\\u0627 \\u0628\\u062F\\u0644 \\u0645\\u0627 \\u0646\\u0644\\u0627\\u0642\\u064A \\u0627\\u0644\\u062C\\u0645\\u0647\\u0648\\u0631."
t["We've got a chance together. I'd rather take it than hide."] = "\\u0645\\u0639\\u0646\\u0627 \\u0641\\u0631\\u0635\\u0629 \\u0633\\u0648\\u0627. \\u0648\\u0628\\u0641\\u0636\\u0651\\u0644 \\u0622\\u062E\\u062F\\u0647\\u0627 \\u0639\\u0644\\u0649 \\u0625\\u0646\\u064A \\u0627\\u062A\\u062E\\u0628\\u0649."
t["We've got food for soup, but no pot to make it in."] = "\\u0639\\u0646\\u0627 \\u0623\\u0643\\u0644 \\u0644\\u0644\\u0634\\u0648\\u0631\\u0628\\u0629\\u060C \\u0628\\u0633 \\u0645\\u0627 \\u0641\\u064A \\u0637\\u0646\\u062C\\u0631\\u0629."
t["We've got illness in the house. Talk from there."] = "\\u0639\\u0646\\u0627 \\u0645\\u0631\\u0636 \\u0628\\u0627\\u0644\\u0628\\u064A\\u062A. \\u0627\\u062D\\u0643\\u064A \\u0645\\u0646 \\u0645\\u0637\\u0631\\u062D\\u0643."
t["We've got someone sick. Give us space to handle it."] = "\\u0639\\u0646\\u0627 \\u062D\\u062F\\u0627 \\u0645\\u0631\\u064A\\u0636. \\u0627\\u0639\\u0637\\u064A\\u0646\\u0627 \\u0645\\u062C\\u0627\\u0644 \\u0646\\u062A\\u062F\\u0628\\u0631."
t["We've got you. Let me stop the bleeding."] = "\\u0645\\u0639\\u0643 \\u0646\\u062D\\u0646\\u0627. \\u062E\\u0644\\u064A\\u0646\\u064A \\u0648\\u0642\\u0641 \\u0627\\u0644\\u062F\\u0645."
t["Weapon condition is critical. Replacing it first."] = "\\u062D\\u0627\\u0644\\u0629 \\u0627\\u0644\\u0633\\u0644\\u0627\\u062D \\u062E\\u0637\\u0631\\u0629. \\u0628\\u062F\\u064A \\u0628\\u062F\\u0644\\u0647 \\u0623\\u0648\\u0644."
t["Weird thought just arrived. It can walk with us a while."] = "\\u0648\\u0635\\u0644\\u062A \\u0641\\u0643\\u0631\\u0629 \\u063A\\u0631\\u064A\\u0628\\u0629. \\u0641\\u064A\\u0647\\u0627 \\u062A\\u0645\\u0634\\u064A \\u0645\\u0639\\u0646\\u0627 \\u0634\\u0648\\u064A."
t["Weird thought: I miss strangers. Ordinary, rude, living sons of bitches."] = "\\u0641\\u0643\\u0631\\u0629 \\u063A\\u0631\\u064A\\u0628\\u0629: \\u0627\\u0634\\u062A\\u0642\\u062A \\u0644\\u0644\\u063A\\u0631\\u0628\\u0627. \\u0639\\u0627\\u062F\\u064A\\u064A\\u0646\\u060C \\u0648\\u0642\\u062D\\u064A\\u0646\\u060C \\u0639\\u0627\\u064A\\u0634\\u064A\\u0646\\u060C \\u0648\\u0644\\u0627\\u062F \\u0643\\u0644\\u0628."
t["Weird thought: I miss strangers. Ordinary, rude, living strangers."] = "\\u0641\\u0643\\u0631\\u0629 \\u063A\\u0631\\u064A\\u0628\\u0629: \\u0627\\u0634\\u062A\\u0642\\u062A \\u0644\\u0644\\u063A\\u0631\\u0628\\u0627. \\u0639\\u0627\\u062F\\u064A\\u064A\\u0646\\u060C \\u0648\\u0642\\u062D\\u064A\\u0646\\u060C \\u0639\\u0627\\u064A\\u0634\\u064A\\u0646."
t["Welcome to Knox County. Enjoy your stay. It's mandatory."] = "\\u0623\\u0647\\u0644\\u0627 \\u0628\\u0646\\u0648\\u0643\\u0633. \\u0646\\u062A\\u0645\\u0646\\u0649 \\u0644\\u0643 \\u0625\\u0642\\u0627\\u0645\\u0629 \\u0637\\u064A\\u0628\\u0629. \\u0625\\u062C\\u0628\\u0627\\u0631\\u064A\\u0629."
t["Well, look at us. We have %1 now."] = "\\u0634\\u0648\\u0641 \\u062D\\u0627\\u0644\\u0646\\u0627. \\u0635\\u0627\\u0631 \\u0639\\u0646\\u0627 %1."
t["Well, shit. Now I need a drink."] = "\\u064A\\u062E\\u0631\\u0628 \\u0628\\u064A\\u062A\\u0647\\u0627. \\u0647\\u0644\\u0623 \\u0635\\u0627\\u0631 \\u0628\\u062F\\u064A \\u0643\\u0627\\u0633."
t["Well, that was a lot of noise for nothing."] = "\\u0637\\u064A\\u0628\\u060C \\u0643\\u0644 \\u0647\\u0627\\u0644\\u0636\\u062C\\u0629 \\u0639\\u0627\\u0644\\u0641\\u0627\\u0636\\u064A."
t["Well, the river gave me rubbish."] = "\\u0637\\u064A\\u0628\\u060C \\u0627\\u0644\\u0646\\u0647\\u0631 \\u0639\\u0637\\u0627\\u0646\\u064A \\u0632\\u0628\\u0627\\u0644\\u0629."
t["Well. Now I need a drink."] = "\\u0637\\u064A\\u0628. \\u0647\\u0644\\u0623 \\u0635\\u0627\\u0631 \\u0628\\u062F\\u064A \\u0643\\u0627\\u0633."
t["Well. That failed. We plant again."] = "\\u0637\\u064A\\u0628. \\u0641\\u0634\\u0644\\u062A. \\u0645\\u0646\\u0631\\u062C\\u0639 \\u0646\\u0632\\u0631\\u0639."
t["Well. That happened."] = "\\u0637\\u064A\\u0628. \\u0635\\u0627\\u0631 \\u0627\\u0644\\u0644\\u064A \\u0635\\u0627\\u0631."
t["Well. That's done now. Let's not be standing near it."] = "\\u0637\\u064A\\u0628. \\u062E\\u0644\\u0635\\u062A. \\u062E\\u0644\\u064A\\u0646\\u0627 \\u0645\\u0627 \\u0646\\u0636\\u0644 \\u0648\\u0627\\u0642\\u0641\\u064A\\u0646 \\u062C\\u0646\\u0628\\u0647\\u0627."
t["Well. We're adults. Let's be adults and keep moving."] = "\\u0637\\u064A\\u0628. \\u0646\\u062D\\u0646\\u0627 \\u0643\\u0628\\u0627\\u0631. \\u062E\\u0644\\u064A\\u0646\\u0627 \\u0646\\u0643\\u0648\\u0646 \\u0643\\u0628\\u0627\\u0631 \\u0648\\u0646\\u0643\\u0645\\u0644."
t["Wet fields might give us something to grow next month."] = "\\u0627\\u0644\\u0623\\u0631\\u0627\\u0636\\u064A \\u0627\\u0644\\u0645\\u0628\\u0644\\u0648\\u0644\\u0629 \\u064A\\u0645\\u0643\\u0646 \\u062A\\u0639\\u0637\\u064A\\u0646\\u0627 \\u0634\\u064A \\u0646\\u0632\\u0631\\u0639\\u0647 \\u0627\\u0644\\u0634\\u0647\\u0631 \\u0627\\u0644\\u062C\\u0627\\u064A."
t["Wet roads and poor visibility. We adjust our pace."] = "\\u0637\\u0631\\u0642\\u0627\\u062A \\u0645\\u0628\\u0644\\u0648\\u0644\\u0629 \\u0648\\u0631\\u0624\\u064A\\u0629 \\u0636\\u0639\\u064A\\u0641\\u0629. \\u0645\\u0646\\u062E\\u0641\\u0641 \\u0627\\u0644\\u0633\\u0631\\u0639\\u0629."
t["What did your kitchen sound like before all this, %1?"] = "\\u0643\\u064A\\u0641 \\u0643\\u0627\\u0646 \\u0635\\u0648\\u062A \\u0645\\u0637\\u0628\\u062E\\u0643 \\u0642\\u0628\\u0644 \\u0643\\u0644 \\u0647\\u0627\\u062F \\u064A\\u0627 %1\\u061F"
t["What good is courage if it never lets anyone else be afraid?"] = "\\u0634\\u0648 \\u0646\\u0641\\u0639 \\u0627\\u0644\\u0634\\u062C\\u0627\\u0639\\u0629 \\u0625\\u0630\\u0627 \\u0645\\u0627 \\u0628\\u062A\\u0633\\u0645\\u062D \\u0644\\u062D\\u062F\\u0627 \\u064A\\u062E\\u0627\\u0641\\u061F"
t["What if Fort Knox is fine and nobody told us."] = "\\u0634\\u0648 \\u0625\\u0630\\u0627 \\u0641\\u0648\\u0631\\u062A \\u0646\\u0648\\u0643\\u0633 \\u062A\\u0645\\u0627\\u0645 \\u0648\\u0645\\u0627 \\u062D\\u062F\\u0627 \\u062E\\u0628\\u0631\\u0646\\u0627."
t["What if I challenged the whole night to a fair fight."] = "\\u0634\\u0648 \\u0625\\u0630\\u0627 \\u062A\\u062D\\u062F\\u064A\\u062A \\u0627\\u0644\\u0644\\u064A\\u0644 \\u0643\\u0644\\u0647 \\u0644\\u0642\\u062A\\u0627\\u0644 \\u0639\\u0627\\u062F\\u0644."
t["What if I'm already scratched and haven't noticed. Checked. Fine. Checking again."] = "\\u0634\\u0648 \\u0625\\u0630\\u0627 \\u0623\\u0646\\u0627 \\u0645\\u062E\\u0631\\u0645\\u0634\\u0629 \\u0648\\u0645\\u0627 \\u0627\\u0646\\u062A\\u0628\\u0647\\u062A. \\u062A\\u0641\\u0642\\u062F\\u062A. \\u062A\\u0645\\u0627\\u0645. \\u0631\\u062D \\u0627\\u062A\\u0641\\u0642\\u062F \\u0643\\u0645\\u0627\\u0646 \\u0645\\u0631\\u0629."
t["What if a salesman knocks. What do we even say."] = "\\u0634\\u0648 \\u0625\\u0630\\u0627 \\u062F\\u0642 \\u0627\\u0644\\u0628\\u0627\\u0628 \\u0628\\u064A\\u0651\\u0627\\u0639. \\u0634\\u0648 \\u0645\\u0646\\u0642\\u0648\\u0644 \\u0623\\u0635\\u0644\\u064B\\u0627."
t["What if every closed door is closed for a reason."] = "\\u0634\\u0648 \\u0625\\u0630\\u0627 \\u0643\\u0644 \\u0628\\u0627\\u0628 \\u0645\\u0633\\u0643\\u0631\\u060C \\u0645\\u0633\\u0643\\u0631 \\u0644\\u0633\\u0628\\u0628."
t["What if it happens tonight? While we're asleep?"] = "\\u0648\\u0625\\u0630\\u0627 \\u0635\\u0627\\u0631\\u062A \\u0627\\u0644\\u0644\\u064A\\u0644\\u0629\\u061F \\u0648\\u0646\\u062D\\u0646\\u0627 \\u0646\\u0627\\u064A\\u0645\\u064A\\u0646\\u061F"
t["What if one day all this is just a story we tell badly."] = "\\u0634\\u0648 \\u0625\\u0630\\u0627 \\u064A\\u0648\\u0645 \\u0645\\u0646 \\u0627\\u0644\\u0623\\u064A\\u0627\\u0645 \\u0643\\u0644 \\u0647\\u0627\\u062F \\u0635\\u0627\\u0631 \\u0642\\u0635\\u0629 \\u0645\\u0646\\u062D\\u0643\\u064A\\u0647\\u0627 \\u0628\\u0634\\u0643\\u0644 \\u0639\\u0627\\u0637\\u0644."
t["What if someone left us a fruit basket. Welcome to the end."] = "\\u0634\\u0648 \\u0625\\u0630\\u0627 \\u062D\\u062F\\u0627 \\u062A\\u0631\\u0643\\u0644\\u0646\\u0627 \\u0633\\u0644\\u0629 \\u0641\\u0648\\u0627\\u0643\\u0647. \\u0623\\u0647\\u0644\\u0627 \\u0628\\u0627\\u0644\\u0646\\u0647\\u0627\\u064A\\u0629."
t["What if the Army comes back and hands out parking tickets. Bastards would, too."] = "\\u0634\\u0648 \\u0625\\u0630\\u0627 \\u0631\\u062C\\u0639 \\u0627\\u0644\\u062C\\u064A\\u0634 \\u0648\\u0648\\u0632\\u0639 \\u0645\\u062E\\u0627\\u0644\\u0641\\u0627\\u062A \\u0648\\u0642\\u0648\\u0641. \\u0648\\u0644\\u0627\\u062F \\u0627\\u0644\\u0643\\u0644\\u0628 \\u0628\\u064A\\u0639\\u0645\\u0644\\u0648\\u0647\\u0627."
t["What if the Army comes back and just hands out parking tickets."] = "\\u0634\\u0648 \\u0625\\u0630\\u0627 \\u0631\\u062C\\u0639 \\u0627\\u0644\\u062C\\u064A\\u0634 \\u0648\\u0628\\u0633 \\u0648\\u0632\\u0639 \\u0645\\u062E\\u0627\\u0644\\u0641\\u0627\\u062A \\u0648\\u0642\\u0648\\u0641."
t["What if the barricade is fine and I'm the weak point."] = "\\u0634\\u0648 \\u0625\\u0630\\u0627 \\u0627\\u0644\\u0645\\u062A\\u0631\\u0627\\u0633 \\u062A\\u0645\\u0627\\u0645 \\u0648\\u0623\\u0646\\u0627 \\u0646\\u0642\\u0637\\u0629 \\u0627\\u0644\\u0636\\u0639\\u0641."
t["What if the barricade's fine and I'm the weak goddamn point."] = "\\u0634\\u0648 \\u0625\\u0630\\u0627 \\u0627\\u0644\\u0645\\u062A\\u0631\\u0627\\u0633 \\u062A\\u0645\\u0627\\u0645 \\u0648\\u0623\\u0646\\u0627 \\u0646\\u0642\\u0637\\u0629 \\u0627\\u0644\\u0636\\u0639\\u0641 \\u0627\\u0644\\u0645\\u0644\\u0639\\u0648\\u0646\\u0629."
t["What if the careful ones just die last. That's the whole prize."] = "\\u0634\\u0648 \\u0625\\u0630\\u0627 \\u0627\\u0644\\u062D\\u0630\\u0631\\u064A\\u0646 \\u0628\\u0633 \\u0628\\u064A\\u0645\\u0648\\u062A\\u0648\\u0627 \\u0622\\u062E\\u0631 \\u0634\\u064A. \\u0648\\u0647\\u064A \\u0643\\u0644 \\u0627\\u0644\\u062C\\u0627\\u064A\\u0632\\u0629."
t["What if the dead are just very, very late for work."] = "\\u0634\\u0648 \\u0625\\u0630\\u0627 \\u0627\\u0644\\u0645\\u064A\\u062A\\u064A\\u0646 \\u0628\\u0633 \\u0645\\u062A\\u0623\\u062E\\u0631\\u064A\\u0646 \\u0643\\u062A\\u064A\\u0631 \\u0639\\u0627\\u0644\\u062F\\u0648\\u0627\\u0645."
t["What if the dead just want to sit in a nice chair too."] = "\\u0634\\u0648 \\u0625\\u0630\\u0627 \\u0627\\u0644\\u0645\\u064A\\u062A\\u064A\\u0646 \\u0643\\u0645\\u0627\\u0646 \\u0628\\u062F\\u0647\\u0645 \\u064A\\u0642\\u0639\\u062F\\u0648\\u0627 \\u0639\\u0643\\u0631\\u0633\\u064A \\u062D\\u0644\\u0648."
t["What if the place is haunted and the ghost is just annoyed."] = "\\u0634\\u0648 \\u0625\\u0630\\u0627 \\u0627\\u0644\\u0645\\u062D\\u0644 \\u0645\\u0633\\u0643\\u0648\\u0646 \\u0648\\u0627\\u0644\\u0634\\u0628\\u062D \\u0628\\u0633 \\u0645\\u062A\\u0636\\u0627\\u064A\\u0642."
t["What if they remember the way home better than we do."] = "\\u0634\\u0648 \\u0625\\u0630\\u0627 \\u0628\\u064A\\u062A\\u0630\\u0643\\u0631\\u0648\\u0627 \\u0637\\u0631\\u064A\\u0642 \\u0627\\u0644\\u0628\\u064A\\u062A \\u0623\\u062D\\u0633\\u0646 \\u0645\\u0646\\u0627."
t["What if this is the good part. What if it gets worse."] = "\\u0634\\u0648 \\u0625\\u0630\\u0627 \\u0647\\u0627\\u062F \\u0627\\u0644\\u062C\\u0632\\u0621 \\u0627\\u0644\\u062D\\u0644\\u0648. \\u0634\\u0648 \\u0625\\u0630\\u0627 \\u0631\\u062D \\u064A\\u0635\\u064A\\u0631 \\u0623\\u0639\\u0648\\u0633."
t["What if this is the night. I think that every damn night."] = "\\u0634\\u0648 \\u0625\\u0630\\u0627 \\u0647\\u0627\\u064A \\u0627\\u0644\\u0644\\u064A\\u0644\\u0629. \\u0628\\u0641\\u0643\\u0631 \\u0647\\u064A\\u0643 \\u0643\\u0644 \\u0644\\u064A\\u0644\\u0629 \\u064A\\u0644\\u0639\\u0646\\u0647\\u0627."
t["What if this is the night. I think that every night."] = "\\u0634\\u0648 \\u0625\\u0630\\u0627 \\u0647\\u0627\\u064A \\u0627\\u0644\\u0644\\u064A\\u0644\\u0629. \\u0628\\u0641\\u0643\\u0631 \\u0647\\u064A\\u0643 \\u0643\\u0644 \\u0644\\u064A\\u0644\\u0629."
t["What we know is:"] = "\\u0627\\u0644\\u0644\\u064A \\u0645\\u0646\\u0639\\u0631\\u0641\\u0647:"
t["What would I do, if it were me. Nothing, probably. Nothing."] = "\\u0634\\u0648 \\u0628\\u0639\\u0645\\u0644\\u060C \\u0644\\u0648 \\u0643\\u0627\\u0646\\u062A \\u0623\\u0646\\u0627. \\u0648\\u0644\\u0627 \\u0634\\u064A\\u060C \\u063A\\u0627\\u0644\\u0628\\u064B\\u0627. \\u0648\\u0644\\u0627 \\u0634\\u064A."
t["What you need to understand is:"] = "\\u0627\\u0644\\u0644\\u064A \\u0644\\u0627\\u0632\\u0645 \\u062A\\u0641\\u0647\\u0645\\u0647:"
t["Whatever happens next, you are not facing it alone."] = "\\u0634\\u0648 \\u0645\\u0627 \\u0635\\u0627\\u0631 \\u0628\\u0639\\u062F\\u064A\\u0646\\u060C \\u0645\\u0648 \\u0631\\u062D \\u062A\\u0648\\u0627\\u062C\\u0647\\u0647 \\u0644\\u062D\\u0627\\u0644\\u0643."
t["Whatever happens, they should not face it alone."] = "\\u0634\\u0648 \\u0645\\u0627 \\u0635\\u0627\\u0631\\u060C \\u0644\\u0627\\u0632\\u0645 \\u0645\\u0627 \\u064A\\u0648\\u0627\\u062C\\u0647\\u0648\\u0647 \\u0644\\u062D\\u0627\\u0644\\u0647\\u0646."
t["Whatever place we find, I want you there."] = "\\u0648\\u064A\\u0646 \\u0645\\u0627 \\u0644\\u0642\\u064A\\u0646\\u0627 \\u0645\\u0637\\u0631\\u062D\\u060C \\u0628\\u062F\\u064A \\u064A\\u0627\\u0643 \\u062A\\u0643\\u0648\\u0646 \\u0645\\u0639\\u064A."
t["Whatever started this started somewhere. This room looks guilty."] = "\\u0627\\u0644\\u0644\\u064A \\u0628\\u0644\\u0651\\u0634 \\u0643\\u0644 \\u0647\\u0627\\u062F \\u0628\\u0644\\u0651\\u0634 \\u0628\\u0645\\u062D\\u0644 \\u0645\\u0627. \\u0647\\u0627\\u0644\\u0623\\u0648\\u0636\\u0629 \\u0634\\u0643\\u0644\\u0647\\u0627 \\u0645\\u0630\\u0646\\u0628\\u0629."
t["Whatever time is left, let's make it kind."] = "\\u0634\\u0648 \\u0645\\u0627 \\u0636\\u0644 \\u0645\\u0646 \\u0648\\u0642\\u062A\\u060C \\u062E\\u0644\\u064A\\u0646\\u0627 \\u0646\\u062E\\u0644\\u064A\\u0647 \\u062D\\u0646\\u0648\\u0646."
t["Whatever wakes in this body, it cannot have what we were."] = "\\u0634\\u0648 \\u0645\\u0627 \\u0641\\u0627\\u0642 \\u0628\\u0647\\u0627\\u0644\\u062C\\u0633\\u0645, \\u0645\\u0627 \\u0625\\u0644\\u0647 \\u062D\\u0642 \\u0628\\u0627\\u0644\\u0644\\u064A \\u0643\\u0646\\u0627."
t["Whatever wears my face next is not your friend."] = "\\u0627\\u0644\\u0644\\u064A \\u0631\\u062D \\u064A\\u0644\\u0628\\u0633 \\u0648\\u062C\\u0647\\u064A \\u0628\\u0639\\u062F\\u064A\\u0646 \\u0645\\u0648 \\u0635\\u0627\\u062D\\u0628\\u0643."
t["Whatever you decide, I understand."] = "\\u0634\\u0648 \\u0645\\u0627 \\u0642\\u0631\\u0631\\u062A\\u060C \\u0623\\u0646\\u0627 \\u0641\\u0647\\u0645\\u0627\\u0646\\u0629."
t["Wheelchairs by the door. Nobody came back to fold them."] = "\\u0643\\u0631\\u0627\\u0633\\u064A \\u0645\\u062A\\u062D\\u0631\\u0643\\u0629 \\u062C\\u0646\\u0628 \\u0627\\u0644\\u0628\\u0627\\u0628. \\u0645\\u0627 \\u062D\\u062F\\u0627 \\u0631\\u062C\\u0639 \\u064A\\u0637\\u0648\\u064A\\u0647\\u0627."
t["When I get back up, that won't be me."] = "\\u0644\\u0645\\u0627 \\u0642\\u0648\\u0645, \\u0647\\u0627\\u062F \\u0645\\u0648 \\u0631\\u062D \\u064A\\u0643\\u0648\\u0646 \\u0623\\u0646\\u0627."
t["When I stop answering, it's done. Don't wait for me to come back."] = "\\u0644\\u0645\\u0627 \\u0648\\u0642\\u0641 \\u062C\\u0627\\u0648\\u0628\\u060C \\u0628\\u062A\\u0643\\u0648\\u0646 \\u062E\\u0644\\u0635\\u062A. \\u0644\\u0627 \\u062A\\u0633\\u062A\\u0646\\u0649 \\u0631\\u062C\\u0639."
t["When are we making the next supply run?"] = "\\u0625\\u064A\\u0645\\u062A \\u0645\\u0634\\u0648\\u0627\\u0631 \\u0627\\u0644\\u0645\\u0648\\u0646\\u0629 \\u0627\\u0644\\u062C\\u0627\\u064A\\u061F"
t["When the eyes change, go. Promise me."] = "\\u0644\\u0645\\u0627 \\u062A\\u062A\\u063A\\u064A\\u0631 \\u0627\\u0644\\u0639\\u064A\\u0648\\u0646, \\u0631\\u0648\\u062D. \\u0648\\u0639\\u062F\\u0646\\u064A."
t["When you sleep, I check you're breathing. Habit now."] = "\\u0644\\u0645\\u0627 \\u062A\\u0646\\u0627\\u0645\\u060C \\u0628\\u062A\\u0623\\u0643\\u062F \\u0625\\u0646\\u0643 \\u0639\\u0645 \\u062A\\u062A\\u0646\\u0641\\u0633. \\u0635\\u0627\\u0631\\u062A \\u0639\\u0627\\u062F\\u0629."
t["When you think of me, make it one of the good days."] = "\\u0644\\u0645\\u0627 \\u062A\\u062A\\u0630\\u0643\\u0631\\u0646\\u064A, \\u062E\\u0644\\u064A\\u0647\\u0627 \\u0645\\u0646 \\u0627\\u0644\\u0623\\u064A\\u0627\\u0645 \\u0627\\u0644\\u062D\\u0644\\u0648\\u0629."
t["Who am I? No. No, I know. I know. I know who I am."] = "\\u0645\\u064A\\u0646 \\u0623\\u0646\\u0627\\u061F \\u0644\\u0623. \\u0644\\u0623\\u060C \\u0628\\u0639\\u0631\\u0641. \\u0628\\u0639\\u0631\\u0641. \\u0628\\u0639\\u0631\\u0641 \\u0645\\u064A\\u0646 \\u0623\\u0646\\u0627."
t["Who decided a safe house would need this much sweeping?"] = "\\u0645\\u064A\\u0646 \\u0642\\u0631\\u0631 \\u0625\\u0646 \\u0627\\u0644\\u0628\\u064A\\u062A \\u0627\\u0644\\u0622\\u0645\\u0646 \\u0628\\u062F\\u0648 \\u0643\\u0644 \\u0647\\u0627\\u0644\\u0643\\u0646\\u0633\\u061F"
t["Who keeps leaving the door open? Oh. It's me. It was me."] = "\\u0645\\u064A\\u0646 \\u0628\\u064A\\u0636\\u0644 \\u064A\\u062A\\u0631\\u0643 \\u0627\\u0644\\u0628\\u0627\\u0628 \\u0645\\u0641\\u062A\\u0648\\u062D\\u061F \\u0622\\u0647. \\u0623\\u0646\\u0627. \\u0643\\u0646\\u062A \\u0623\\u0646\\u0627."
t["Who keeps leaving the goddamn door open? Oh. It's me. It was me."] = "\\u0645\\u064A\\u0646 \\u0628\\u064A\\u0636\\u0644 \\u064A\\u062A\\u0631\\u0643 \\u0627\\u0644\\u0628\\u0627\\u0628 \\u0627\\u0644\\u0645\\u0644\\u0639\\u0648\\u0646 \\u0645\\u0641\\u062A\\u0648\\u062D\\u061F \\u0622\\u0647. \\u0623\\u0646\\u0627. \\u0643\\u0646\\u062A \\u0623\\u0646\\u0627."
t["Who was the last person to vacuum in Kentucky? I need to know."] = "\\u0645\\u064A\\u0646 \\u0622\\u062E\\u0631 \\u0648\\u0627\\u062D\\u062F \\u0643\\u0646\\u0651\\u0633 \\u0628\\u0627\\u0644\\u0645\\u0643\\u0646\\u0633\\u0629 \\u0627\\u0644\\u0643\\u0647\\u0631\\u0628\\u0627 \\u0628\\u0643\\u0646\\u062A\\u0627\\u0643\\u064A\\u061F \\u0644\\u0627\\u0632\\u0645 \\u0627\\u0639\\u0631\\u0641."
t["Whoa! Give me a little room."] = "\\u0623\\u0648\\u0641! \\u0648\\u0633\\u0639\\u0644\\u064A \\u0634\\u0648\\u064A."
t["Whoever built this fence hated knees."] = "\\u0627\\u0644\\u0644\\u064A \\u0639\\u0645\\u0631 \\u0647\\u0627\\u0644\\u0633\\u0648\\u0631 \\u0643\\u0627\\u0646 \\u0643\\u0627\\u0631\\u0647 \\u0627\\u0644\\u0631\\u0643\\u0628."
t["Whoever keeps that transmitter alive deserves a meal."] = "\\u0627\\u0644\\u0644\\u064A \\u0639\\u0645 \\u064A\\u062E\\u0644\\u064A \\u0647\\u0627\\u0644\\u0645\\u0631\\u0633\\u0644\\u0629 \\u0639\\u0627\\u064A\\u0634\\u0629 \\u0628\\u064A\\u0633\\u062A\\u0627\\u0647\\u0644 \\u0623\\u0643\\u0644\\u0629."
t["Whoever taped this gave us a quiet hour."] = "\\u064A\\u0633\\u0644\\u0645\\u0648\\u0627 \\u0625\\u064A\\u062F\\u064A\\u0646 \\u0627\\u0644\\u0644\\u064A \\u0633\\u062C\\u0644 \\u0647\\u0627\\u062F\\u060C \\u0639\\u0637\\u0627\\u0646\\u0627 \\u0633\\u0627\\u0639\\u0629 \\u0647\\u062F\\u0648\\u0621."
t["Whole circle wants a fight. I'm punching through one side."] = "\\u0627\\u0644\\u062F\\u0627\\u064A\\u0631\\u0629 \\u0643\\u0644\\u0647\\u0627 \\u0628\\u062F\\u0647\\u0627 \\u062E\\u0646\\u0627\\u0642\\u0629. \\u0639\\u0645 \\u0627\\u062E\\u062A\\u0631\\u0642 \\u0645\\u0646 \\u062C\\u0647\\u0629 \\u0648\\u062D\\u062F\\u0629."
t["Whole county, and not one person left to wave at."] = "\\u0645\\u0642\\u0627\\u0637\\u0639\\u0629 \\u0643\\u0627\\u0645\\u0644\\u0629\\u060C \\u0648\\u0645\\u0627 \\u0641\\u064A \\u062D\\u062F\\u0627 \\u0627\\u0633\\u0644\\u0651\\u0645 \\u0639\\u0644\\u064A\\u0647."
t["Whole damn county, and not one person left to wave at."] = "\\u0645\\u0642\\u0627\\u0637\\u0639\\u0629 \\u0643\\u0627\\u0645\\u0644\\u0629 \\u064A\\u0644\\u0639\\u0646\\u060C \\u0648\\u0645\\u0627 \\u0641\\u064A \\u062D\\u062F\\u0627 \\u0627\\u0633\\u0644\\u0651\\u0645 \\u0639\\u0644\\u064A\\u0647."
t["Why are you still moving?"] = "\\u0644\\u064A\\u0634 \\u0644\\u0633\\u0627 \\u0639\\u0645 \\u062A\\u062A\\u062D\\u0631\\u0643?"
t["Why is it always two?!"] = "\\u0644\\u064A\\u0634 \\u062F\\u0627\\u064A\\u0645\\u0627 \\u062A\\u0646\\u064A\\u0646?!"
t["Why me? Why did it have to be me?"] = "\\u0644\\u064A\\u0634 \\u0623\\u0646\\u0627\\u061F \\u0644\\u064A\\u0634 \\u0644\\u0627\\u0632\\u0645 \\u0643\\u0648\\u0646 \\u0623\\u0646\\u0627\\u061F"
t["Why won't you die?"] = "\\u0644\\u064A\\u0634 \\u0645\\u0627 \\u0628\\u062A\\u0645\\u0648\\u062A?"
t["Why won't you stay dead?!"] = "\\u0644\\u064A\\u0634 \\u0645\\u0627 \\u0628\\u062F\\u0643 \\u062A\\u0636\\u0644 \\u0645\\u064A\\u062A?!"
t["Wind's wrong. Give me another second."] = "\\u0627\\u0644\\u0647\\u0648\\u0627 \\u0645\\u0648 \\u0645\\u0646 \\u0627\\u0644\\u062C\\u0647\\u0629 \\u0627\\u0644\\u0635\\u062D. \\u0639\\u0637\\u064A\\u0646\\u064A \\u062B\\u0627\\u0646\\u064A\\u0629 \\u0643\\u0645\\u0627\\u0646."
t["Windshield cleaner's still here. Priorities survived."] = "\\u0645\\u0646\\u0638\\u0641 \\u0627\\u0644\\u0632\\u062C\\u0627\\u062C \\u0644\\u0633\\u0627 \\u0647\\u0648\\u0646. \\u0627\\u0644\\u0623\\u0648\\u0644\\u0648\\u064A\\u0627\\u062A \\u0646\\u062C\\u064A\\u062A."
t["Withdraw while the exit is still open."] = "\\u0627\\u0646\\u0633\\u062D\\u0628 \\u0637\\u0627\\u0644\\u0645\\u0627 \\u0627\\u0644\\u0645\\u062E\\u0631\\u062C \\u0644\\u0633\\u0627 \\u0645\\u0641\\u062A\\u0648\\u062D."
t["Withdrawal route is compromised. Holding here."] = "\\u0637\\u0631\\u064A\\u0642 \\u0627\\u0644\\u0627\\u0646\\u0633\\u062D\\u0627\\u0628 \\u0627\\u0646\\u0643\\u0634\\u0641. \\u0628\\u0627\\u0642\\u064A\\u0629 \\u0647\\u0648\\u0646."
t["Work blocked: no serviceable digging tool."] = "\\u0627\\u0644\\u0634\\u063A\\u0644 \\u0648\\u0627\\u0642\\u0641: \\u0645\\u0627 \\u0641\\u064A \\u0639\\u062F\\u0629 \\u062D\\u0641\\u0631 \\u0635\\u0627\\u0644\\u062D\\u0629."
t["Working the list is the only thing keeping me level."] = "\\u0627\\u0644\\u0634\\u063A\\u0644 \\u0639\\u0627\\u0644\\u0642\\u0627\\u064A\\u0645\\u0629 \\u0647\\u0648 \\u0627\\u0644\\u0634\\u064A \\u0627\\u0644\\u0648\\u062D\\u064A\\u062F \\u0627\\u0644\\u0644\\u064A \\u0639\\u0645 \\u064A\\u062E\\u0644\\u064A\\u0646\\u064A \\u0648\\u0627\\u0642\\u0641\\u0629."
t["Works for me. Give me a moment to pack."] = "\\u0628\\u062A\\u0645\\u0634\\u064A \\u0645\\u0639\\u064A. \\u0639\\u0637\\u064A\\u0646\\u064A \\u0644\\u062D\\u0638\\u0629 \\u0648\\u0636\\u0651\\u0628."
t["World ended and I'm still on shift. Figures."] = "\\u062E\\u0644\\u0635\\u062A \\u0627\\u0644\\u062F\\u0646\\u064A\\u0627 \\u0648\\u0623\\u0646\\u0627 \\u0644\\u0633\\u0627 \\u0628\\u0627\\u0644\\u062F\\u0648\\u0627\\u0645. \\u0637\\u0628\\u064A\\u0639\\u064A."
t["Worth the wait, this one."] = "\\u0628\\u062A\\u0633\\u062A\\u0627\\u0647\\u0644 \\u0627\\u0644\\u0627\\u0646\\u062A\\u0638\\u0627\\u0631 \\u0647\\u064A."
t["Would you keep me company while I eat? Just for a few minutes."] = "\\u0628\\u062A\\u0642\\u0639\\u062F \\u0645\\u0639\\u064A \\u0648\\u0623\\u0646\\u0627 \\u0628\\u0627\\u0643\\u0644\\u061F \\u0628\\u0633 \\u0643\\u0627\\u0645 \\u062F\\u0642\\u064A\\u0642\\u0629."
t["Would you look at that: %1!"] = "\\u0634\\u0648\\u0641 \\u0647\\u0627\\u0644\\u062D\\u0644\\u0627\\u0648\\u0629: %1!"
t["Write down what I know. Where the supplies are. While I still remember."] = "\\u0627\\u0643\\u062A\\u0628 \\u0627\\u0644\\u0644\\u064A \\u0628\\u0639\\u0631\\u0641\\u0647. \\u0648\\u064A\\u0646 \\u0627\\u0644\\u0645\\u0648\\u0646\\u0629. \\u0637\\u0627\\u0644\\u0645\\u0627 \\u0644\\u0633\\u0627 \\u0645\\u062A\\u0630\\u0643\\u0631\\u0629."
t["Wrong road, stranger. Back up."] = "\\u063A\\u0644\\u0637\\u0627\\u0646 \\u0628\\u0627\\u0644\\u0637\\u0631\\u064A\\u0642 \\u064A\\u0627 \\u063A\\u0631\\u064A\\u0628. \\u0627\\u0631\\u062C\\u0639."
t["Yeah. I think about that too."] = "\\u0625\\u064A. \\u0648\\u0623\\u0646\\u0627 \\u0643\\u0645\\u0627\\u0646 \\u0628\\u0641\\u0643\\u0631 \\u0641\\u064A\\u0647\\u0627."
t["Yeah. I've heard it."] = "\\u0625\\u064A. \\u0633\\u0645\\u0639\\u062A\\u0647\\u0627."
t["Yes. We will look after each other."] = "\\u0625\\u064A. \\u0643\\u0644 \\u0648\\u0627\\u062D\\u062F \\u0628\\u064A\\u062F\\u064A\\u0631 \\u0628\\u0627\\u0644\\u0647 \\u0639\\u0627\\u0644\\u062A\\u0627\\u0646\\u064A."
t["Yield collected and ready to sort."] = "\\u0627\\u0644\\u063A\\u0644\\u0629 \\u0627\\u0646\\u0644\\u0645\\u0651\\u062A \\u0648\\u062C\\u0627\\u0647\\u0632\\u0629 \\u0644\\u0644\\u0641\\u0631\\u0632."
t["Yield is in. Keep the seed separate."] = "\\u0627\\u0644\\u0645\\u062D\\u0635\\u0648\\u0644 \\u0635\\u0627\\u0631 \\u062C\\u0648\\u0627. \\u0627\\u0641\\u0635\\u0644 \\u0627\\u0644\\u0628\\u0632\\u0627\\u0631 \\u0644\\u062D\\u0627\\u0644\\u0647."
t["Yoo-hoo! Fresh meat, other direction!"] = "\\u064A\\u0627 \\u0647\\u0648! \\u0644\\u062D\\u0645\\u0629 \\u0637\\u0627\\u0632\\u0629\\u060C \\u0645\\u0646 \\u0647\\u0648\\u0646!"
t["You all right? That one sounded heavy."] = "\\u0625\\u0646\\u062A \\u0645\\u0646\\u064A\\u062D\\u061F \\u0647\\u064A \\u0637\\u0644\\u0639\\u062A \\u062A\\u0642\\u064A\\u0644\\u0629."
t["You all right? You've gone real quiet on me."] = "\\u0625\\u0646\\u062A \\u0645\\u0646\\u064A\\u062D\\u061F \\u0633\\u0643\\u062A\\u062A \\u0643\\u062A\\u064A\\u0631 \\u0641\\u062C\\u0623\\u0629."
t["You already helped. I just need a little time now."] = "\\u0633\\u0627\\u0639\\u062F\\u062A\\u0646\\u064A \\u0648\\u062E\\u0644\\u0635\\u062A. \\u0628\\u0633 \\u0628\\u062F\\u064A \\u0634\\u0648\\u064A\\u0629 \\u0648\\u0642\\u062A \\u0647\\u0644\\u0623."
t["You always came back for me, %1. This time, live with walking away."] = "\\u062F\\u0627\\u064A\\u0645\\u0627 \\u0643\\u0646\\u062A \\u062A\\u0631\\u062C\\u0639\\u0644\\u064A \\u064A\\u0627 %1. \\u0647\\u0627\\u0644\\u0645\\u0631\\u0629 \\u0639\\u064A\\u0634 \\u0648\\u0627\\u0645\\u0634\\u064A."
t["You always came back for me. Come back now!"] = "\\u062F\\u0627\\u064A\\u0645\\u0627 \\u0643\\u0646\\u062A \\u062A\\u0631\\u062C\\u0639\\u0644\\u064A. \\u0627\\u0631\\u062C\\u0639 \\u0647\\u0644\\u0623!"
t["You are close enough. Stay where you are."] = "\\u0647\\u0648\\u0646 \\u0628\\u064A\\u0643\\u0641\\u064A. \\u062E\\u0644\\u064A\\u0643 \\u0645\\u0637\\u0631\\u062D\\u0643."
t["You are family to me now. I am not walking away."] = "\\u0623\\u0646\\u062A \\u0635\\u0631\\u062A \\u0623\\u0647\\u0644\\u064A. \\u0645\\u0648 \\u0631\\u0627\\u064A\\u062D\\u0629 \\u0644\\u0645\\u062D\\u0644."
t["You are not getting through me!"] = "\\u0645\\u0627 \\u0631\\u062D \\u062A\\u0645\\u0631\\u0642 \\u0645\\u0646 \\u0639\\u0646\\u062F\\u064A!"
t["You are welcome at the gate."] = "\\u0623\\u0647\\u0644\\u0627 \\u0641\\u064A\\u0643 \\u0639\\u0627\\u0644\\u0628\\u0648\\u0627\\u0628\\u0629."
t["You aren't walking that off. Give me a minute."] = "\\u0645\\u0627 \\u0631\\u062D \\u062A\\u0645\\u0634\\u064A\\u0647\\u0627 \\u0647\\u064A\\u0643. \\u0639\\u0637\\u064A\\u0646\\u064A \\u062F\\u0642\\u064A\\u0642\\u0629."
t["You asked for this. Defend yourself."] = "\\u0625\\u0646\\u062A \\u0627\\u0644\\u0644\\u064A \\u0637\\u0644\\u0628\\u062A\\u0647\\u0627. \\u062F\\u0627\\u0641\\u0639 \\u0639\\u0646 \\u062D\\u0627\\u0644\\u0643."
t["You broke the truce. I'm fighting for my life."] = "\\u062E\\u0631\\u0642\\u062A \\u0627\\u0644\\u0647\\u062F\\u0646\\u0629. \\u0639\\u0645 \\u0642\\u0627\\u062A\\u0644 \\u0639\\u0644\\u0649 \\u062D\\u064A\\u0627\\u062A\\u064A."
t["You came back for me every time. You can't this time."] = "\\u0643\\u0644 \\u0645\\u0631\\u0629 \\u0643\\u0646\\u062A \\u062A\\u0631\\u062C\\u0639\\u0644\\u064A. \\u0647\\u0627\\u0644\\u0645\\u0631\\u0629 \\u0645\\u0627 \\u0641\\u064A\\u0643."
t["You came back for me. Thank you."] = "\\u0631\\u062C\\u0639\\u062A \\u0644\\u0639\\u0646\\u062F\\u064A. \\u0634\\u0643\\u0631\\u0627 \\u0625\\u0644\\u0643."
t["You can almost smell the wet fields through the walls."] = "\\u0641\\u064A\\u0643 \\u062A\\u0634\\u0645 \\u0631\\u064A\\u062D\\u0629 \\u0627\\u0644\\u0623\\u0631\\u0627\\u0636\\u064A \\u0627\\u0644\\u0645\\u0628\\u0644\\u0648\\u0644\\u0629 \\u0645\\u0646 \\u0648\\u0631\\u0627 \\u0627\\u0644\\u062D\\u064A\\u0637\\u0627\\u0646."
t["You can approach the gate, no farther."] = "\\u0641\\u064A\\u0643 \\u062A\\u0648\\u0635\\u0644 \\u0639\\u0627\\u0644\\u0628\\u0648\\u0627\\u0628\\u0629\\u060C \\u0648\\u0628\\u0633."
t["You can ask. Whether the door opens depends on how you behave."] = "\\u0641\\u064A\\u0643 \\u062A\\u0633\\u0623\\u0644. \\u0627\\u0644\\u0628\\u0627\\u0628 \\u0628\\u064A\\u0646\\u0641\\u062A\\u062D \\u0623\\u0648 \\u0644\\u0623 \\u062D\\u0633\\u0628 \\u062A\\u0635\\u0631\\u0641\\u0643."
t["You can hear how empty it is. Nobody warns you about the quiet."] = "\\u0641\\u064A\\u0643 \\u062A\\u0633\\u0645\\u0639 \\u0642\\u062F\\u064A\\u0634 \\u0641\\u0627\\u0636\\u064A\\u0629. \\u0645\\u0627 \\u062D\\u062F\\u0627 \\u0628\\u064A\\u062D\\u0630\\u0631\\u0643 \\u0645\\u0646 \\u0627\\u0644\\u0633\\u0643\\u0648\\u062A."
t["You can talk to us here. The door isn't part of the invitation."] = "\\u0641\\u064A\\u0643 \\u062A\\u062D\\u0643\\u064A \\u0645\\u0639\\u0646\\u0627 \\u0647\\u0648\\u0646. \\u0627\\u0644\\u0628\\u0627\\u0628 \\u0645\\u0648 \\u062F\\u0627\\u062E\\u0644 \\u0628\\u0627\\u0644\\u0639\\u0632\\u064A\\u0645\\u0629."
t["You caught me with that one. Slow down."] = "\\u0625\\u062C\\u062A \\u0641\\u064A\\u0646\\u064A \\u0647\\u064A. \\u0639\\u0645\\u0647\\u0644\\u0643."
t["You caught the edge of something. Sit tight."] = "\\u062C\\u0631\\u062D\\u0643 \\u0637\\u0631\\u0641 \\u0634\\u064A. \\u062E\\u0644\\u064A\\u0643 \\u0645\\u0643\\u0627\\u0646\\u0643."
t["You chose this after I stopped. Remember that."] = "\\u0625\\u0646\\u062A \\u0627\\u062E\\u062A\\u0631\\u062A \\u0647\\u0627\\u062F \\u0628\\u0639\\u062F \\u0645\\u0627 \\u0648\\u0642\\u0641\\u062A. \\u062A\\u0630\\u0643\\u0631."
t["You chose this, stranger!"] = "\\u0625\\u0646\\u062A \\u0627\\u0644\\u0644\\u064A \\u0627\\u062E\\u062A\\u0631\\u062A \\u064A\\u0627 \\u063A\\u0631\\u064A\\u0628!"
t["You deserve something good for once. Here."] = "\\u0628\\u062A\\u0633\\u062A\\u0627\\u0647\\u0644 \\u0634\\u064A \\u062D\\u0644\\u0648 \\u0644\\u0645\\u0631\\u0629. \\u062E\\u062F."
t["You do your share. That's a decent place to start."] = "\\u0628\\u062A\\u0639\\u0645\\u0644 \\u0627\\u0644\\u0644\\u064A \\u0639\\u0644\\u064A\\u0643. \\u0648\\u0647\\u064A \\u0628\\u062F\\u0627\\u064A\\u0629 \\u0645\\u0642\\u0628\\u0648\\u0644\\u0629."
t["You don't have to earn your place with me every morning."] = "\\u0645\\u0648 \\u0644\\u0627\\u0632\\u0645 \\u062A\\u062B\\u0628\\u062A \\u0645\\u0637\\u0631\\u062D\\u0643 \\u0639\\u0646\\u062F\\u064A \\u0643\\u0644 \\u064A\\u0648\\u0645 \\u0627\\u0644\\u0635\\u0628\\u062D."
t["You don't have to fix this one, %1."] = "\\u0645\\u0648 \\u0644\\u0627\\u0632\\u0645 \\u062A\\u0635\\u0644\\u062D \\u0647\\u064A \\u064A\\u0627 %1."
t["You don't have to make yourself useful to matter to me."] = "\\u0645\\u0648 \\u0644\\u0627\\u0632\\u0645 \\u062A\\u0643\\u0648\\u0646 \\u0645\\u0641\\u064A\\u062F \\u0644\\u062A\\u0641\\u0631\\u0642 \\u0645\\u0639\\u064A."
t["You don't have to say anything. Just stay a minute."] = "\\u0645\\u0648 \\u0644\\u0627\\u0632\\u0645 \\u062A\\u062D\\u0643\\u064A \\u0634\\u064A. \\u0628\\u0633 \\u062E\\u0644\\u064A\\u0643 \\u062F\\u0642\\u064A\\u0642\\u0629."
t["You don't have to talk. Just stay while I finish eating."] = "\\u0645\\u0648 \\u0644\\u0627\\u0632\\u0645 \\u062A\\u062D\\u0643\\u064A. \\u0628\\u0633 \\u062E\\u0644\\u064A\\u0643 \\u0644\\u062E\\u0644\\u0635 \\u0623\\u0643\\u0644."
t["You earned every piece of trust I had left to give."] = "\\u0627\\u0633\\u062A\\u0627\\u0647\\u0644\\u062A \\u0643\\u0644 \\u0630\\u0631\\u0629 \\u062B\\u0642\\u0629 \\u0643\\u0627\\u0646\\u062A \\u0628\\u0627\\u0642\\u064A\\u0629 \\u0639\\u0646\\u062F\\u064A."
t["You found me when I had nobody. That mattered."] = "\\u0644\\u0642\\u064A\\u062A\\u0646\\u064A \\u0644\\u0645\\u0627 \\u0645\\u0627 \\u0643\\u0627\\u0646 \\u0639\\u0646\\u062F\\u064A \\u062D\\u062F\\u0627. \\u0647\\u0627\\u062F \\u0641\\u0631\\u0642 \\u0643\\u062A\\u064A\\u0631."
t["You gave me a reason to call somewhere home, %1."] = "\\u0639\\u0637\\u064A\\u062A\\u0646\\u064A \\u0633\\u0628\\u0628 \\u0642\\u0648\\u0644 \\u0639\\u0646 \\u0645\\u0643\\u0627\\u0646 \\u0628\\u064A\\u062A\\u064A \\u064A\\u0627 %1."
t["You gave me more days than I thought I had. Thank you."] = "\\u0639\\u0637\\u064A\\u062A\\u0646\\u064A \\u0623\\u064A\\u0627\\u0645 \\u0623\\u0643\\u062A\\u0631 \\u0645\\u0646 \\u0627\\u0644\\u0644\\u064A \\u0643\\u0646\\u062A \\u062D\\u0627\\u0633\\u0628\\u062A\\u0647\\u0627. \\u0634\\u0643\\u0631\\u0627."
t["You gave me people worth saying goodbye to."] = "\\u0639\\u0637\\u064A\\u062A\\u0646\\u064A \\u0646\\u0627\\u0633 \\u0628\\u064A\\u0633\\u062A\\u0627\\u0647\\u0644\\u0648\\u0627 \\u0627\\u0644\\u0648\\u062F\\u0627\\u0639."
t["You got your warning. I'm walking off."] = "\\u0627\\u062A\\u062D\\u0630\\u0631\\u062A. \\u0623\\u0646\\u0627 \\u0645\\u0627\\u0634\\u064A\\u0629."
t["You had your way out. You threw it away."] = "\\u0643\\u0627\\u0646 \\u0639\\u0646\\u062F\\u0643 \\u0645\\u062E\\u0631\\u062C. \\u0631\\u0645\\u064A\\u062A\\u0647."
t["You have been fair with me so far."] = "\\u0644\\u0647\\u0644\\u0623 \\u0643\\u0646\\u062A \\u0645\\u0646\\u0635\\u0641 \\u0645\\u0639\\u064A."
t["You have been quiet, %1. Want some company?"] = "\\u0633\\u0627\\u0643\\u062A \\u064A\\u0627 %1. \\u0628\\u062F\\u0643 \\u0648\\u0646\\u0633\\u061F"
t["You have earned my trust."] = "\\u0627\\u0633\\u062A\\u0627\\u0647\\u0644\\u062A \\u062B\\u0642\\u062A\\u064A."
t["You have one chance left to walk away."] = "\\u0628\\u0627\\u0642\\u064A\\u0644\\u0643 \\u0641\\u0631\\u0635\\u0629 \\u0648\\u062D\\u062F\\u0629 \\u062A\\u0641\\u0644."
t["You have proven yourself to me more than once."] = "\\u0623\\u062B\\u0628\\u062A\\u0651\\u0644\\u064A \\u062D\\u0627\\u0644\\u0643 \\u0623\\u0643\\u062A\\u0631 \\u0645\\u0646 \\u0645\\u0631\\u0629."
t["You have to leave before my face lies to you."] = "\\u0644\\u0627\\u0632\\u0645 \\u062A\\u0641\\u0644 \\u0642\\u0628\\u0644 \\u0645\\u0627 \\u064A\\u0643\\u0630\\u0628 \\u0639\\u0644\\u064A\\u0643 \\u0648\\u062C\\u0647\\u064A."
t["You have to tell them. Now. Or I will."] = "\\u0644\\u0627\\u0632\\u0645 \\u062A\\u062E\\u0628\\u0631\\u0647\\u0646. \\u0647\\u0644\\u0623. \\u0648\\u0625\\u0644\\u0627 \\u0623\\u0646\\u0627 \\u0628\\u062E\\u0628\\u0631\\u0647\\u0646."
t["You haven't given me a reason to leave. Don't rush the rest."] = "\\u0644\\u0633\\u0627 \\u0645\\u0627 \\u0639\\u0637\\u064A\\u062A\\u0646\\u064A \\u0633\\u0628\\u0628 \\u0627\\u0645\\u0634\\u064A. \\u0644\\u0627 \\u062A\\u0633\\u062A\\u0639\\u062C\\u0644 \\u0639\\u0627\\u0644\\u0628\\u0627\\u0642\\u064A."
t["You hit me after I let you go. This ends here."] = "\\u0636\\u0631\\u0628\\u062A\\u0646\\u064A \\u0628\\u0639\\u062F \\u0645\\u0627 \\u062A\\u0631\\u0643\\u062A\\u0643. \\u0647\\u0648\\u0646 \\u0628\\u062A\\u062E\\u0644\\u0635."
t["You hit me again. What am I supposed to think?"] = "\\u0636\\u0631\\u0628\\u062A\\u0646\\u064A \\u0643\\u0645\\u0627\\u0646 \\u0645\\u0631\\u0629. \\u0634\\u0648 \\u0628\\u062F\\u0643 \\u0627\\u0641\\u0643\\u0631\\u061F"
t["You keep swinging my way, I'm moving out."] = "\\u0625\\u0630\\u0627 \\u0628\\u062A\\u0636\\u0644 \\u062A\\u0636\\u0631\\u0628 \\u0635\\u0648\\u0628\\u064A\\u060C \\u0623\\u0646\\u0627 \\u0637\\u0627\\u0644\\u0639\\u0629."
t["You knew me as I became, not only as I was. Thank you."] = "\\u0639\\u0631\\u0641\\u062A\\u0646\\u064A \\u0645\\u062A\\u0644 \\u0645\\u0627 \\u0635\\u0631\\u062A, \\u0645\\u0648 \\u0628\\u0633 \\u0645\\u062A\\u0644 \\u0645\\u0627 \\u0643\\u0646\\u062A. \\u0634\\u0643\\u0631\\u0627."
t["You knew the real me. Do not let the infection rewrite that memory."] = "\\u0639\\u0631\\u0641\\u062A \\u062D\\u0642\\u064A\\u0642\\u062A\\u064A. \\u0644\\u0627 \\u062A\\u062E\\u0644\\u064A \\u0627\\u0644\\u0639\\u062F\\u0648\\u0649 \\u062A\\u0643\\u062A\\u0628 \\u0647\\u0627\\u0644\\u0630\\u0643\\u0631\\u0649 \\u0645\\u0646 \\u062C\\u062F\\u064A\\u062F."
t["You know I'd crawl through them for you. Please try for me!"] = "\\u0628\\u062A\\u0639\\u0631\\u0641 \\u0643\\u0646\\u062A \\u0628\\u0632\\u062D\\u0641 \\u0645\\u0646 \\u0628\\u064A\\u0646\\u0627\\u062A\\u0646 \\u0639\\u0634\\u0627\\u0646\\u0643. \\u062C\\u0631\\u0628 \\u0639\\u0634\\u0627\\u0646\\u064A!"
t["You know what has to be done afterward."] = "\\u0628\\u062A\\u0639\\u0631\\u0641 \\u0634\\u0648 \\u0644\\u0627\\u0632\\u0645 \\u064A\\u0646\\u0639\\u0645\\u0644 \\u0628\\u0639\\u062F\\u064A\\u0646."
t["You know, %1, this almost feels like a normal evening."] = "\\u0628\\u062A\\u0639\\u0631\\u0641 \\u064A\\u0627 %1\\u060C \\u062A\\u0642\\u0631\\u064A\\u0628\\u0627\\u064B \\u0645\\u062A\\u0644 \\u0633\\u0647\\u0631\\u0629 \\u0639\\u0627\\u062F\\u064A\\u0629."
t["You lead. I'll listen behind us."] = "\\u0627\\u0645\\u0634\\u064A \\u0642\\u062F\\u0627\\u0645\\u064A. \\u0623\\u0646\\u0627 \\u0628\\u0633\\u0645\\u0639 \\u0634\\u0648 \\u0648\\u0631\\u0627\\u0646\\u0627."
t["You left the exit exposed back there. I am not letting that slide."] = "\\u062A\\u0631\\u0643\\u062A \\u0627\\u0644\\u0645\\u062E\\u0631\\u062C \\u0645\\u0643\\u0634\\u0648\\u0641 \\u0647\\u0646\\u064A\\u0643. \\u0648\\u0623\\u0646\\u0627 \\u0645\\u0627 \\u0631\\u062D \\u0627\\u0633\\u0643\\u062A."
t["You look tired, %1. Talk to me."] = "\\u0634\\u0643\\u0644\\u0643 \\u062A\\u0639\\u0628\\u0627\\u0646 \\u064A\\u0627 %1. \\u0627\\u062D\\u0643\\u064A\\u0644\\u064A."
t["You lost the right to call me a friend."] = "\\u062E\\u0633\\u0631\\u062A \\u062D\\u0642\\u0643 \\u062A\\u0642\\u0648\\u0644 \\u0639\\u0646\\u064A \\u0635\\u0627\\u062D\\u0628\\u062A\\u0643."
t["You made me do this. Back off!"] = "\\u0625\\u0646\\u062A \\u062C\\u0628\\u0631\\u062A\\u0646\\u064A. \\u0627\\u0628\\u0639\\u062F!"
t["You made me myself again, %1. Remember me that way."] = "\\u0631\\u062C\\u0639\\u062A\\u0646\\u064A \\u0644\\u062D\\u0627\\u0644\\u064A \\u064A\\u0627 %1. \\u062A\\u0630\\u0643\\u0631\\u0646\\u064A \\u0647\\u064A\\u0643."
t["You made me want tomorrow again."] = "\\u062E\\u0644\\u064A\\u062A\\u0646\\u064A \\u0627\\u0634\\u062A\\u0647\\u064A \\u0628\\u0643\\u0631\\u0627 \\u0645\\u0646 \\u062C\\u062F\\u064A\\u062F."
t["You made the end of the world feel less lonely."] = "\\u062E\\u0644\\u064A\\u062A \\u0646\\u0647\\u0627\\u064A\\u0629 \\u0627\\u0644\\u0639\\u0627\\u0644\\u0645 \\u0623\\u0642\\u0644 \\u0648\\u062D\\u062F\\u0629."
t["You made this broken world feel like a life again, %1."] = "\\u062E\\u0644\\u064A\\u062A \\u0647\\u0627\\u0644\\u062F\\u0646\\u064A\\u0627 \\u0627\\u0644\\u0645\\u0643\\u0633\\u0648\\u0631\\u0629 \\u062A\\u0631\\u062C\\u0639 \\u062D\\u064A\\u0627\\u0629 \\u064A\\u0627 %1."
t["You need a hobby. Or a nap. Possibly both."] = "\\u0628\\u062F\\u0643 \\u0647\\u0648\\u0627\\u064A\\u0629. \\u0623\\u0648 \\u0646\\u0648\\u0645\\u0629. \\u064A\\u0645\\u0643\\u0646 \\u0627\\u0644\\u062A\\u0646\\u062A\\u064A\\u0646."
t["You need help, not another blow."] = "\\u0625\\u0646\\u062A \\u0628\\u062F\\u0643 \\u0645\\u0633\\u0627\\u0639\\u062F\\u0629\\u060C \\u0645\\u0648 \\u0636\\u0631\\u0628\\u0629 \\u062A\\u0627\\u0646\\u064A\\u0629."
t["You need rest too. Promise me you'll remember that."] = "\\u0625\\u0646\\u062A \\u0643\\u0645\\u0627\\u0646 \\u0628\\u062F\\u0643 \\u0631\\u0627\\u062D\\u0629. \\u0648\\u0639\\u062F\\u0646\\u064A \\u0645\\u0627 \\u062A\\u0646\\u0633\\u0649."
t["You never listen until something goes wrong!"] = "\\u0639\\u0645\\u0631\\u0643 \\u0645\\u0627 \\u0628\\u062A\\u0633\\u0645\\u0639 \\u0644\\u062A\\u062E\\u0631\\u0628 \\u0627\\u0644\\u062F\\u0646\\u064A\\u0627!"
t["You noticing matters. More than I'd like to admit."] = "\\u0625\\u0646\\u0648 \\u062A\\u0646\\u062A\\u0628\\u0647 \\u0628\\u064A\\u0641\\u0631\\u0642. \\u0623\\u0643\\u062A\\u0631 \\u0645\\u0645\\u0627 \\u0628\\u062D\\u0628 \\u0627\\u0639\\u062A\\u0631\\u0641."
t["You pulled me out of that - thank you."] = "\\u0625\\u0646\\u062A \\u0627\\u0644\\u0644\\u064A \\u0637\\u0644\\u0639\\u062A\\u0646\\u064A - \\u0634\\u0643\\u0631\\u0627."
t["You said the last run was safe!"] = "\\u0642\\u0644\\u062A \\u0627\\u0644\\u0645\\u0634\\u0648\\u0627\\u0631 \\u0627\\u0644\\u0623\\u062E\\u064A\\u0631 \\u0622\\u0645\\u0646!"
t["You said we'd watch each other's backs - they're on mine!"] = "\\u0642\\u0644\\u062A \\u0645\\u0646\\u062D\\u0645\\u064A \\u0636\\u0647\\u0631 \\u0628\\u0639\\u0636 - \\u0648\\u0647\\u0644\\u0623 \\u0647\\u0646\\u0646 \\u0639\\u0636\\u0647\\u0631\\u064A!"
t["You say these things out loud on purpose."] = "\\u0625\\u0646\\u062A \\u0642\\u0627\\u0635\\u062F \\u062A\\u0642\\u0648\\u0644 \\u0647\\u0627\\u0644\\u062D\\u0643\\u064A \\u0628\\u0635\\u0648\\u062A \\u0639\\u0627\\u0644\\u064A."
t["You should have let me walk away."] = "\\u0643\\u0627\\u0646 \\u0644\\u0627\\u0632\\u0645 \\u062A\\u062E\\u0644\\u064A\\u0646\\u064A \\u0627\\u0645\\u0634\\u064A."
t["You should hear this from me. I've been bitten."] = "\\u0644\\u0627\\u0632\\u0645 \\u062A\\u0633\\u0645\\u0639\\u0647\\u0627 \\u0645\\u0646\\u064A. \\u0623\\u0646\\u0627 \\u0627\\u0646\\u0639\\u0636\\u0651\\u064A\\u062A."
t["You started this. I'm ending it!"] = "\\u0625\\u0646\\u062A \\u0628\\u0644\\u0634\\u062A\\u0647\\u0627. \\u0648\\u0623\\u0646\\u0627 \\u0631\\u062D \\u062E\\u0644\\u0635\\u0647\\u0627!"
t["You stayed. That helped more than you probably know."] = "\\u0636\\u0644\\u064A\\u062A. \\u0648\\u0647\\u0627\\u0644\\u0634\\u064A \\u0641\\u0627\\u062F\\u0646\\u064A \\u0623\\u0643\\u062A\\u0631 \\u0645\\u0645\\u0627 \\u0628\\u062A\\u062A\\u062E\\u064A\\u0644."
t["You struck while I backed off. Never again."] = "\\u0636\\u0631\\u0628\\u062A\\u0646\\u064A \\u0648\\u0623\\u0646\\u0627 \\u0639\\u0645 \\u0627\\u0631\\u062C\\u0639. \\u0645\\u0627 \\u0639\\u0627\\u062F \\u0628\\u062A\\u062A\\u0643\\u0631\\u0631."
t["You swing again, I fight. Understand?"] = "\\u0628\\u062A\\u0636\\u0631\\u0628 \\u0643\\u0645\\u0627\\u0646\\u060C \\u0628\\u0642\\u0627\\u062A\\u0644\\u0643. \\u0641\\u0647\\u0645\\u062A\\u061F"
t["You think I don't replay it in my head? I did what I could."] = "\\u0645\\u0641\\u0643\\u0631\\u0646\\u064A \\u0645\\u0627 \\u0628\\u0639\\u064A\\u062F\\u0647\\u0627 \\u0628\\u0631\\u0627\\u0633\\u064A\\u061F \\u0639\\u0645\\u0644\\u062A \\u0627\\u0644\\u0644\\u064A \\u0642\\u062F\\u0631\\u062A \\u0639\\u0644\\u064A\\u0647."
t["You think you're the first to point that out?"] = "\\u0645\\u0641\\u0643\\u0631 \\u062D\\u0627\\u0644\\u0643 \\u0623\\u0648\\u0644 \\u0648\\u0627\\u062D\\u062F \\u0628\\u064A\\u0646\\u062A\\u0628\\u0647\\u061F"
t["You took in a stranger. Do not let what I become punish you for that kindness."] = "\\u0622\\u0648\\u064A\\u062A \\u0648\\u062D\\u062F\\u0629 \\u063A\\u0631\\u064A\\u0628\\u0629. \\u0644\\u0627 \\u062A\\u062E\\u0644\\u064A \\u0627\\u0644\\u0644\\u064A \\u0631\\u062D \\u0635\\u064A\\u0631\\u0647 \\u064A\\u0639\\u0627\\u0642\\u0628\\u0643 \\u0639\\u0627\\u0644\\u0644\\u0637\\u0641."
t["You want a fight? You've got one!"] = "\\u0628\\u062F\\u0643 \\u062E\\u0646\\u0627\\u0642\\u0629\\u061F \\u0637\\u064A\\u0628!"
t["You want my trust? Be there when it gets ugly."] = "\\u0628\\u062F\\u0643 \\u062B\\u0642\\u062A\\u064A\\u061F \\u0643\\u0648\\u0646 \\u0645\\u0648\\u062C\\u0648\\u062F \\u0644\\u0645\\u0627 \\u062A\\u0633\\u0648\\u062F \\u0627\\u0644\\u062F\\u0646\\u064A\\u0627."
t["You wanted to keep fighting. So fight."] = "\\u0628\\u062F\\u0643 \\u062A\\u0643\\u0645\\u0644 \\u0642\\u062A\\u0627\\u0644\\u061F \\u064A\\u0644\\u0627 \\u0642\\u0627\\u062A\\u0644."
t["You were a good partner, %1. Find another reason to keep going."] = "\\u0643\\u0646\\u062A \\u0634\\u0631\\u064A\\u0643 \\u0645\\u0646\\u064A\\u062D \\u064A\\u0627 %1. \\u0644\\u0627\\u0642\\u064A \\u0633\\u0628\\u0628 \\u062A\\u0627\\u0646\\u064A \\u0644\\u062A\\u0643\\u0645\\u0644."
t["You were a good partner, %1. I could not have asked for fairer."] = "\\u0643\\u0646\\u062A \\u0634\\u0631\\u064A\\u0643 \\u0645\\u0646\\u064A\\u062D \\u064A\\u0627 %1. \\u0645\\u0627 \\u0643\\u0646\\u062A \\u0644\\u0627\\u0642\\u064A \\u0623\\u0646\\u0635\\u0641 \\u0645\\u0646\\u0643."
t["You were family when I thought family was gone."] = "\\u0643\\u0646\\u062A \\u0639\\u064A\\u0644\\u062A\\u064A \\u0644\\u0645\\u0627 \\u0641\\u0643\\u0631\\u062A \\u0627\\u0644\\u0639\\u064A\\u0644\\u0629 \\u0631\\u0627\\u062D\\u062A."
t["You were home to me after every other home was gone."] = "\\u0643\\u0646\\u062A \\u0628\\u064A\\u062A\\u064A \\u0628\\u0639\\u062F \\u0645\\u0627 \\u0631\\u0627\\u062D\\u062A \\u0643\\u0644 \\u0627\\u0644\\u0628\\u064A\\u0648\\u062A."
t["You were my partner while I was human. Keep that part of me."] = "\\u0643\\u0646\\u062A \\u0634\\u0631\\u064A\\u0643\\u064A \\u0648\\u0623\\u0646\\u0627 \\u0625\\u0646\\u0633\\u0627\\u0646\\u0629. \\u062E\\u0644\\u064A \\u0647\\u0627\\u0644\\u062C\\u0632\\u0621 \\u0645\\u0646\\u064A \\u0645\\u0639\\u0643."
t["You were warned!"] = "\\u062D\\u0630\\u0631\\u0646\\u0627\\u0643!"
t["You would have done the same for me."] = "\\u0643\\u0646\\u062A \\u0631\\u062D \\u062A\\u0639\\u0645\\u0644 \\u0646\\u0641\\u0633 \\u0627\\u0644\\u0634\\u064A \\u0639\\u0634\\u0627\\u0646\\u064A."
t["You'll have to do better than that!"] = "\\u0628\\u062F\\u0643 \\u062A\\u062C\\u0631\\u0628 \\u0623\\u062D\\u0633\\u0646 \\u0645\\u0646 \\u0647\\u064A\\u0643!"
t["You're clear. I'll keep my back turned."] = "\\u0627\\u0644\\u0637\\u0631\\u064A\\u0642 \\u0646\\u0636\\u064A\\u0641. \\u0639\\u0627\\u0637\\u064A\\u0629 \\u0636\\u0647\\u0631\\u064A."
t["You're close enough to hurt me. Don't."] = "\\u0635\\u0631\\u062A \\u0642\\u0631\\u064A\\u0628 \\u0644\\u062F\\u0631\\u062C\\u0629 \\u062A\\u0642\\u062F\\u0631 \\u062A\\u0648\\u062C\\u0639\\u0646\\u064A. \\u0644\\u0627 \\u062A\\u0639\\u0645\\u0644\\u0647\\u0627."
t["You're family. That means I get to tell you when you're being stupid."] = "\\u0625\\u0646\\u062A \\u0623\\u0647\\u0644\\u064A. \\u064A\\u0639\\u0646\\u064A \\u0645\\u0646 \\u062D\\u0642\\u064A \\u0642\\u0644\\u0643 \\u0644\\u0645\\u0627 \\u062A\\u0643\\u0648\\u0646 \\u0639\\u0645 \\u062A\\u062A\\u063A\\u0627\\u0628\\u0649."
t["You're family. That's one thing this mess doesn't get to decide."] = "\\u0625\\u0646\\u062A \\u0623\\u0647\\u0644\\u064A. \\u0648\\u0647\\u064A \\u0634\\u063A\\u0644\\u0629 \\u0645\\u0627 \\u0628\\u062A\\u0642\\u0631\\u0631\\u0647\\u0627 \\u0647\\u0627\\u0644\\u0628\\u0644\\u0648\\u0629."
t["You're here. I was hoping you'd keep being here."] = "\\u0625\\u0646\\u062A \\u0647\\u0648\\u0646. \\u0643\\u0646\\u062A \\u0622\\u0645\\u0644\\u0629 \\u062A\\u0636\\u0644 \\u0647\\u0648\\u0646."
t["You're hurt enough. I'm done fighting."] = "\\u0628\\u0643\\u0641\\u064A\\u0643 \\u0648\\u062C\\u0639. \\u062E\\u0644\\u0635\\u062A \\u0642\\u062A\\u0627\\u0644."
t["You're on dish duty for that one."] = "\\u0645\\u0634\\u0627\\u0646 \\u0647\\u0627\\u0644\\u062D\\u0643\\u064A\\u060C \\u0627\\u0644\\u062C\\u0644\\u064A \\u0639\\u0644\\u064A\\u0643."
t["You're right. A house gets fixed one stubborn piece at a time."] = "\\u0645\\u0639\\u0643 \\u062D\\u0642. \\u0627\\u0644\\u0628\\u064A\\u062A \\u0628\\u064A\\u062A\\u0635\\u0644\\u062D \\u0642\\u0637\\u0639\\u0629 \\u0639\\u0646\\u064A\\u062F\\u0629 \\u0648\\u0631\\u0627 \\u0642\\u0637\\u0639\\u0629."
t["You're the only one I'd tell. It's a bite."] = "\\u0625\\u0646\\u062A \\u0627\\u0644\\u0648\\u062D\\u064A\\u062F \\u0627\\u0644\\u0644\\u064A \\u0628\\u062E\\u0628\\u0631\\u0647. \\u0647\\u064A \\u0639\\u0636\\u0629."
t["You're the reason I kept going - don't stop now!"] = "\\u0625\\u0646\\u062A \\u0627\\u0644\\u0633\\u0628\\u0628 \\u0627\\u0644\\u0644\\u064A \\u062E\\u0644\\u0627\\u0646\\u064A \\u0643\\u0645\\u0644 - \\u0644\\u0627 \\u062A\\u0648\\u0642\\u0641 \\u0647\\u0644\\u0623!"
t["You're welcome at the entry. Let's hear what you need."] = "\\u0623\\u0647\\u0644\\u0627 \\u0641\\u064A\\u0643 \\u0639\\u0627\\u0644\\u0645\\u062F\\u062E\\u0644. \\u062E\\u0644\\u064A\\u0646\\u0627 \\u0646\\u0633\\u0645\\u0639 \\u0634\\u0648 \\u0628\\u062F\\u0643."
t["You've got a deal. I'm with you."] = "\\u0627\\u062A\\u0641\\u0642\\u0646\\u0627. \\u0623\\u0646\\u0627 \\u0645\\u0639\\u0643."
t["You've got cover. Call if you need it."] = "\\u063A\\u0637\\u064A\\u062A\\u0643. \\u0646\\u0627\\u062F\\u064A \\u0625\\u0630\\u0627 \\u0628\\u062F\\u0643 \\u0634\\u064A."
t["You've kept me alive this long. You should know. I got bit."] = "\\u0625\\u0646\\u062A \\u0627\\u0644\\u0644\\u064A \\u062E\\u0644\\u064A\\u062A\\u0646\\u064A \\u0639\\u0627\\u064A\\u0634\\u0629 \\u0644\\u0647\\u0644\\u0623. \\u0644\\u0627\\u0632\\u0645 \\u062A\\u0639\\u0631\\u0641. \\u0627\\u0646\\u0639\\u0636\\u0651\\u064A\\u062A."
t["You've looked after me. Let me give you something back."] = "\\u062F\\u0627\\u064A\\u0645\\u0627 \\u0627\\u0647\\u062A\\u0645\\u064A\\u062A \\u0641\\u064A\\u064A. \\u062E\\u0644\\u064A\\u0646\\u064A \\u0631\\u062C\\u0639\\u0644\\u0643 \\u0634\\u064A."
t["You've never left me behind. Please don't start today!"] = "\\u0639\\u0645\\u0631\\u0643 \\u0645\\u0627 \\u062A\\u0631\\u0643\\u062A\\u0646\\u064A \\u0648\\u0631\\u0627. \\u0644\\u0627 \\u062A\\u0628\\u0644\\u0634 \\u0627\\u0644\\u064A\\u0648\\u0645!"
t["Your fly's down! ...Worth a shot."] = "\\u0633\\u062D\\u0627\\u0628\\u0643 \\u0645\\u0641\\u062A\\u0648\\u062D! ...\\u0628\\u064A\\u0633\\u062A\\u0627\\u0647\\u0644 \\u0627\\u0644\\u0645\\u062D\\u0627\\u0648\\u0644\\u0629."
t["Your head is a scary goddamn neighbourhood."] = "\\u0631\\u0627\\u0633\\u0643 \\u062D\\u0627\\u0631\\u0629 \\u0628\\u062A\\u062E\\u0648\\u0651\\u0641\\u060C \\u064A\\u0644\\u0639\\u0646 \\u0623\\u0628\\u0648\\u0647\\u0627."
t["Your head is a scary neighbourhood."] = "\\u0631\\u0627\\u0633\\u0643 \\u062D\\u0627\\u0631\\u0629 \\u0628\\u062A\\u062E\\u0648\\u0651\\u0641."
t["Your secret. My problem now too."] = "\\u0633\\u0631\\u0643. \\u0648\\u0635\\u0627\\u0631 \\u0645\\u0634\\u0643\\u0644\\u062A\\u064A \\u0623\\u0646\\u0627 \\u0643\\u0645\\u0627\\u0646."
t["Your word has some weight with me now."] = "\\u0635\\u0627\\u0631 \\u0644\\u0643\\u0644\\u0645\\u062A\\u0643 \\u0648\\u0632\\u0646 \\u0639\\u0646\\u062F\\u064A."
t["Zero exits. The approach is rejected."] = "\\u0635\\u0641\\u0631 \\u0645\\u062E\\u0627\\u0631\\u062C. \\u0645\\u0631\\u0641\\u0648\\u0636."
t["Zip up, count heads, and follow me into the gray."] = "\\u0633\\u0643\\u0631\\u0648\\u0627 \\u062C\\u0643\\u064A\\u062A\\u0627\\u062A\\u0643\\u0645\\u060C \\u0639\\u062F\\u0648\\u0627 \\u062D\\u0627\\u0644\\u0643\\u0645\\u060C \\u0648\\u0644\\u062D\\u0642\\u0648\\u0646\\u064A \\u0639\\u0627\\u0644\\u0631\\u0645\\u0627\\u062F\\u064A."
t["Zippee Market. Zip in, zip out, like the jingle said."] = "\\u0633\\u0648\\u0642 \\u0632\\u064A\\u0628\\u064A. \\u0641\\u0648\\u062A \\u0628\\u0633\\u0631\\u0639\\u0629 \\u0648\\u0627\\u0637\\u0644\\u0639 \\u0628\\u0633\\u0631\\u0639\\u0629\\u060C \\u0645\\u062A\\u0644 \\u0645\\u0627 \\u0628\\u062A\\u0642\\u0648\\u0644 \\u0627\\u0644\\u0623\\u063A\\u0646\\u064A\\u0629."
t["Zombie coming in!"] = "\\u0632\\u0648\\u0645\\u0628\\u064A \\u062C\\u0627\\u064A!"
t["Zombie spotted!"] = "\\u0634\\u0641\\u062A \\u0632\\u0648\\u0645\\u0628\\u064A!"
t["Zombie! Check your escape route!"] = "\\u0632\\u0648\\u0645\\u0628\\u064A! \\u0634\\u0648\\u0641 \\u0637\\u0631\\u064A\\u0642 \\u0647\\u0631\\u0628\\u0643!"
t["Zombie! I'll take it!"] = "\\u0632\\u0648\\u0645\\u0628\\u064A! \\u0639\\u0644\\u064A\\u0651!"
